INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (189, '5008', '「{{魔封じの芳香|5008}}」の『①：このカードが魔法＆罠ゾーンに存在する限り、お互いに魔法カードはセットしなければ発動できず、セットしたプレイヤーから見て次の自分ターンが来るまで発動できない』効果が適用されています。\n\nこの状況にて、「{{仮面魔獣デス・ガーディウス|5097}}」がフィールドから墓地へ送られた場合、『①：このカードがフィールドから墓地へ送られた場合、相手フィールドの表側表示モンスター１体を対象として発動する。デッキから「{{遺言の仮面|5098}}」１枚を装備カード扱いとして対象のモンスターに装備する』効果は発動しますか？', '「{{遺言の仮面|5098}}」が装備魔法カード扱いとして魔法＆罠ゾーンに置かれる場合、「{{仮面魔獣デス・ガーディウス|5097}}」の効果の発動によって置かれる事となり、魔法カードの発動が行われる扱いではありません。\n\nしたがって、「{{魔封じの芳香|5008}}」の効果が適用されている場合でも、「{{仮面魔獣デス・ガーディウス|5097}}」の効果は通常通り発動し、その効果処理によって「{{遺言の仮面|5098}}」をモンスターに装備させる事になります。', '魔封ジノ芳香5008ノ①コノカードガ魔法罠ゾーンニ存在スル限リオ互イニ魔法カードハセットシナケレバ発動デキズセットシタプレイヤーカラ見テ次ノ自分ターンガ来ルマデ発動デキナイ効果ガ適用サレテイマスnnコノ状況ニテ仮面魔獣デスガーディウス5097ガフィールドカラ墓地ヘ送ラレタ場合①コノカードガフィールドカラ墓地ヘ送ラレタ場合相手フィールドノ表側表示モンスター1体ヲ対象トシテ発動スルデッキカラ遺言ノ仮面50981枚ヲ装備カード扱イトシテ対象ノモンスターニ装備スル効果ハ発動シマスカ', '遺言ノ仮面5098ガ装備魔法カード扱イトシテ魔法罠ゾーンニ置カレル場合仮面魔獣デスガーディウス5097ノ効果ノ発動ニヨッテ置カレル事トナリ魔法カードノ発動ガ行ワレル扱イデハアリマセンnnシタガッテ魔封ジノ芳香5008ノ効果ガ適用サレテイル場合デモ仮面魔獣デスガーディウス5097ノ効果ハ通常通リ発動シソノ効果処理ニヨッテ遺言ノ仮面5098ヲモンスターニ装備サセル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (188, '11079', '「{{森羅の鎮神 オレイア|11079}}」の『１ターンに１度、このカードのエクシーズ素材を１つ取り除いて発動できる。自分のデッキの上からカードを３枚までめくる。その中に植物族モンスターがあった場合、それらのモンスターを全て墓地へ送り、その数までこのカード以外のフィールド上のカードを選んで手札に戻す。残りのカードは好きな順番でデッキの下に戻す』効果によって、植物族モンスターとドラゴン族モンスターがめくられました。\n\nこの場合、両方のモンスターが墓地へ送られる事になりますか？', '「{{森羅の鎮神 オレイア|11079}}」の効果でめくったデッキのカードの中に、植物族モンスターがあった場合、墓地へ送られるのは植物族モンスターのみです。\n\nしたがって、質問の状況の場合には、植物族モンスターのみが墓地へ送られ、ドラゴン族モンスターはデッキの下に戻す事になります。', '森羅ノ鎮神オレイア11079ノ1ターンニ1度コノカードノエクシーズ素材ヲ1ツ取リ除イテ発動デキル自分ノデッキノ上カラカードヲ3枚マデメクルソノ中ニ植物族モンスターガアッタ場合ソレラノモンスターヲ全テ墓地ヘ送リソノ数マデコノカード以外ノフィールド上ノカードヲ選ンデ手札ニ戻ス残リノカードハ好キナ順番デデッキノ下ニ戻ス効果ニヨッテ植物族モンスタートドラゴン族モンスターガメクラレマシタnnコノ場合両方ノモンスターガ墓地ヘ送ラレル事ニナリマスカ', '森羅ノ鎮神オレイア11079ノ効果デメクッタデッキノカードノ中ニ植物族モンスターガアッタ場合墓地ヘ送ラレルノハ植物族モンスターノミデスnnシタガッテ質問ノ状況ノ場合ニハ植物族モンスターノミガ墓地ヘ送ラレドラゴン族モンスターハデッキノ下ニ戻ス事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (187, '11159', '自分のライフポイントが1000未満の場合でも、「{{ソウル・チャージ|11159}}」を発動する事はできますか？', '自分のライフポイントが1000未満の場合でも、「{{ソウル・チャージ|11159}}」を発動する事はできます。\n\n「{{ソウル・チャージ|11159}}」の効果処理によって、モンスターが特殊召喚された場合、自分はその特殊召喚されたモンスターの数×1000ライフポイントを失う事になりますので、結果的に自分がデュエルに敗北する事になります。', '自分ノライフポイントガ1000未満ノ場合デモソウルチャージ11159ヲ発動スル事ハデキマスカ', '自分ノライフポイントガ1000未満ノ場合デモソウルチャージ11159ヲ発動スル事ハデキマスnnソウルチャージ11159ノ効果処理ニヨッテモンスターガ特殊召喚サレタ場合自分ハソノ特殊召喚サレタモンスターノ数×1000ライフポイントヲ失ウ事ニナリマスノデ結果的ニ自分ガデュエルニ敗北スル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (186, '4080', '自分のモンスターゾーンに「{{岩石の巨兵|4080}}」と「{{格闘戦士アルティメーター|4106}}」が表側守備表示で存在し、その「{{格闘戦士アルティメーター|4106}}」は「{{結束 UNITY|5755}}」の効果が適用され、守備力が3000になっています。\n\nこの状況で、「{{強制脱出装置|5914}}」が発動し、「{{岩石の巨兵|4080}}」が手札に戻った場合、「{{結束 UNITY|5755}}」の効果によって適用された守備力はどうなりますか？', '「{{結束 UNITY|5755}}」の効果が適用された後、他の自分のモンスターゾーンのモンスターがフィールドに存在しなくなった場合でも、「{{結束 UNITY|5755}}」の効果によって既に適用された守備力は適用されたままとなります。\n（質問の状況の場合、「{{格闘戦士アルティメーター|4106}}」の守備力は3000のままです。）', '自分ノモンスターゾーンニ岩石ノ巨兵4080ト格闘戦士アルティメーター4106ガ表側守備表示デ存在シソノ格闘戦士アルティメーター4106ハ結束unity5755ノ効果ガ適用サレ守備力ガ3000ニナッテイマスnnコノ状況デ強制脱出装置5914ガ発動シ岩石ノ巨兵4080ガ手札ニ戻ッタ場合結束unity5755ノ効果ニヨッテ適用サレタ守備力ハドウナリマスカ', '結束unity5755ノ効果ガ適用サレタ後他ノ自分ノモンスターゾーンノモンスターガフィールドニ存在シナクナッタ場合デモ結束unity5755ノ効果ニヨッテ既ニ適用サレタ守備力ハ適用サレタママトナリマスn質問ノ状況ノ場合格闘戦士アルティメーター4106ノ守備力ハ3000ノママデス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (185, '10456', '「{{ホープ・バスター|10456}}」の発動にチェーンした「{{閃珖竜 スターダスト|10479}}」の効果によって、相手のモンスターゾーンに表側表示で存在する攻撃力が一番低いモンスターに『選択したカードは、このターンに１度だけ戦闘及びカードの効果では破壊されない』効果が適用されている場合、「{{ホープ・バスター|10456}}」の効果処理はどうなりますか？', '質問の状況の場合、「{{ホープ・バスター|10456}}」の効果によって破壊される『相手フィールド上の攻撃力が一番低いモンスター１体』に該当するモンスターに、「{{閃珖竜 スターダスト|10479}}」の効果が適用され破壊されませんので、「{{ホープ・バスター|10456}}」の『破壊したモンスターの攻撃力分のダメージを相手ライフに与える』処理も適用されません。', 'ホープバスター10456ノ発動ニチェーンシタ閃珖龍スターダスト10479ノ効果ニヨッテ相手ノモンスターゾーンニ表側表示デ存在スル攻撃力ガ一番低イモンスターニ選択シタカードハコノターンニ1度ダケ戦闘及ビカードノ効果デハ破壊サレナイ効果ガ適用サレテイル場合ホープバスター10456ノ効果処理ハドウナリマスカ', '質問ノ状況ノ場合ホープバスター10456ノ効果ニヨッテ破壊サレル相手フィールド上ノ攻撃力ガ一番低イモンスター1体ニ該当スルモンスターニ閃珖龍スターダスト10479ノ効果ガ適用サレ破壊サレマセンノデホープバスター10456ノ破壊シタモンスターノ攻撃力分ノダメージヲ相手ライフニ与エル処理モ適用サレマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (184, '8582', '「{{強制終了|8582}}」の効果を発動する際のコストとなる『自分フィールド上に存在するこのカード以外のカード１枚を墓地へ送る』にて、自分フィールドのモンスタートークンを選ぶ事はできますか？', 'モンスタートークンは墓地に送られる事はありませんので、「{{強制終了|8582}}」の効果を発動する際に、モンスタートークンを墓地に送るカードとして選ぶ事はできません。\n（自分フィールドに「{{強制終了|8582}}」とモンスタートークン以外のカードが1枚も存在していないのであれば、「{{強制終了|8582}}」の効果を発動する事自体ができません。）', '強制終了8582ノ効果ヲ発動スル際ノコストトナル自分フィールド上ニ存在スルコノカード以外ノカード1枚ヲ墓地ヘ送ルニテ自分フィールドノモンスタートークンヲ選ブ事ハデキマスカ', 'モンスタートークンハ墓地ニ送ラレル事ハアリマセンノデ強制終了8582ノ効果ヲ発動スル際ニモンスタートークンヲ墓地ニ送ルカードトシテ選ブ事ハデキマセンn自分フィールドニ強制終了8582トモンスタートークン以外ノカードガ1枚モ存在シテイナイノデアレバ強制終了8582ノ効果ヲ発動スル事自体ガデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (182, '4798', '魔法＆罠ゾーンにセットされている「{{トゥーン・ワールド|4798}}」が「{{サイクロン|4909}}」の効果によって破壊された場合、「{{トゥーン・マーメイド|4734}}」は『④：フィールドの「{{トゥーン・ワールド|4798}}」が破壊された時にこのカードは破壊される』の効果によって破壊されますか？', '魔法＆罠ゾーンにセットされている「{{トゥーン・ワールド|4798}}」が「{{サイクロン|4909}}」の効果で破壊された場合には、「{{トゥーン・マーメイド|4734}}」の『④：フィールドの「{{トゥーン・ワールド|4798}}」が破壊された時にこのカードは破壊される』効果は適用されません。', '魔法罠ゾーンニセットサレテイルトゥーンワールド4798ガサイクロン4909ノ効果ニヨッテ破壊サレタ場合トゥーンマーメイド4734ハ④フィールドノトゥーンワールド4798ガ破壊サレタ時ニコノカードハ破壊サレルノ効果ニヨッテ破壊サレマスカ', '魔法罠ゾーンニセットサレテイルトゥーンワールド4798ガサイクロン4909ノ効果デ破壊サレタ場合ニハトゥーンマーメイド4734ノ④フィールドノトゥーンワールド4798ガ破壊サレタ時ニコノカードハ破壊サレル効果ハ適用サレマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (180, '4342', '自分フィールドのシンクロモンスターと、シンクロモンスター以外のモンスターが「{{ブラック・ホール|4342}}」の効果によって同時に破壊され墓地へ送られた時に、「{{シャドー・インパルス|11177}}」を発動する事はできますか？\n\nまた、自分フィールドの２体のシンクロモンスターが「{{ブラック・ホール|4342}}」の効果によって同時に破壊され墓地へ送られた時に、「{{シャドー・インパルス|11177}}」を発動する事はできますか？', '質問のどちらの状況の場合も、「{{シャドー・インパルス|11177}}」を発動する事ができます。\n\nなお、２体のシンクロモンスターが同時に破壊され墓地へ送られた時に「{{シャドー・インパルス|11177}}」を発動する場合には、その破壊された２体のシンクロモンスターの内、いずれか１体を対象として発動する事になります。', '自分フィールドノシンクロモンスタートシンクロモンスター以外ノモンスターガブラックホール4342ノ効果ニヨッテ同時ニ破壊サレ墓地ヘ送ラレタ時ニシャドーインパルス11177ヲ発動スル事ハデキマスカnnマタ自分フィールドノ2体ノシンクロモンスターガブラックホール4342ノ効果ニヨッテ同時ニ破壊サレ墓地ヘ送ラレタ時ニシャドーインパルス11177ヲ発動スル事ハデキマスカ', '質問ノドチラノ状況ノ場合モシャドーインパルス11177ヲ発動スル事ガデキマスnnナオ2体ノシンクロモンスターガ同時ニ破壊サレ墓地ヘ送ラレタ時ニシャドーインパルス11177ヲ発動スル場合ニハソノ破壊サレタ2体ノシンクロモンスターノ内イズレカ1体ヲ対象トシテ発動スル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (179, '10477', '「{{キックファイア|10477}}」が自分の魔法＆罠ゾーンに表側表示で存在しています。\n\nその状況で、「{{ブラック・ホール|4342}}」の効果によって複数体の炎属性モンスターが同時に破壊された場合、「{{キックファイア|10477}}」にカウンターはいくつ置かれますか？', 'そのターンに「{{キックファイア|10477}}」にカウンターを置く処理を適用していないのであれば、「{{ブラック・ホール|4342}}」の効果によって複数体の炎属性モンスターが破壊された際にも「{{キックファイア|10477}}」にカウンターが置かれる事になります。\n\nなお、その時に「{{キックファイア|10477}}」に置かれるカウンターの数は、表側表示で破壊された炎属性モンスターの数になります。\n例えば、表側表示の炎属性モンスター２体と、裏側守備表示の炎属性モンスター１体が、「{{ブラック・ホール|4342}}」の効果で破壊された場合、「{{キックファイア|10477}}」に置かれるカウンターの数は２つになります。', 'キックファイア10477ガ自分ノ魔法罠ゾーンニ表側表示デ存在シテイマスnnソノ状況デブラックホール4342ノ効果ニヨッテ複数体ノ炎属性モンスターガ同時ニ破壊サレタ場合キックファイア10477ニカウンターハイクツ置カレマスカ', 'ソノターンニキックファイア10477ニカウンターヲ置ク処理ヲ適用シテイナイノデアレバブラックホール4342ノ効果ニヨッテ複数体ノ炎属性モンスターガ破壊サレタ際ニモキックファイア10477ニカウンターガ置カレル事ニナリマスnnナオソノ時ニキックファイア10477ニ置カレルカウンターノ数ハ表側表示デ破壊サレタ炎属性モンスターノ数ニナリマスn例エバ表側表示ノ炎属性モンスター2体ト裏側守備表示ノ炎属性モンスター1体ガブラックホール4342ノ効果デ破壊サレタ場合キックファイア10477ニ置カレルカウンターノ数ハ2ツニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (178, '11012', '「{{玄翼竜 ブラック・フェザー|11012}}」自身が戦闘によって破壊された際に、自分が戦闘ダメージを受ける場合、『１ターンに１度、戦闘またはカードの効果によって自分がダメージを受けた時に発動できる。自分のデッキの上からカードを５枚まで墓地へ送る。この効果で墓地へ送ったカードの中にモンスターカードがあった場合、このカードの攻撃力は４００ポイントアップする』効果を発動する事はできますか？', '「{{玄翼竜 ブラック・フェザー|11012}}」自身が戦闘によって破壊された際に、自分が戦闘ダメージを受ける場合でも、「{{玄翼竜 ブラック・フェザー|11012}}」の効果を発動する事ができます。\n\nその場合でも、『自分のデッキの上からカードを5枚まで墓地へ送る』効果処理は通常通り行われます。\n\n（なお、墓地へ送ったカードの中にモンスターカードがあったとしても、デッキのカードを墓地へ送る処理にて処理が完了した扱いとなります。）', '玄翼龍ブラックフェザー11012自身ガ戦闘ニヨッテ破壊サレタ際ニ自分ガ戦闘ダメージヲ受ケル場合1ターンニ1度戦闘マタハカードノ効果ニヨッテ自分ガダメージヲ受ケタ時ニ発動デキル自分ノデッキノ上カラカードヲ5枚マデ墓地ヘ送ルコノ効果デ墓地ヘ送ッタカードノ中ニモンスターカードガアッタ場合コノカードノ攻撃力ハ400ポイントアップスル効果ヲ発動スル事ハデキマスカ', '玄翼龍ブラックフェザー11012自身ガ戦闘ニヨッテ破壊サレタ際ニ自分ガ戦闘ダメージヲ受ケル場合デモ玄翼龍ブラックフェザー11012ノ効果ヲ発動スル事ガデキマスnnソノ場合デモ自分ノデッキノ上カラカードヲ5枚マデ墓地ヘ送ル効果処理ハ通常通リ行ワレマスnnナオ墓地ヘ送ッタカードノ中ニモンスターカードガアッタトシテモデッキノカードヲ墓地ヘ送ル処理ニテ処理ガ完了シタ扱イトナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (177, '10983', '「{{強化蘇生|10983}}」の効果によって「{{霞の谷のファルコン|8109}}」を特殊召喚しています。\n\nその後に、「{{強化蘇生|10983}}」を手札に戻してその「{{霞の谷のファルコン|8109}}」で攻撃宣言した場合、「{{霞の谷のファルコン|8109}}」のレベル・攻撃力・守備力はどうなりますか？\nまた、その攻撃はどうなりますか？', '「{{強化蘇生|10983}}」がフィールドから離れた場合、特殊召喚されている「{{霞の谷のファルコン|8109}}」は「{{強化蘇生|10983}}」の対象から外れるため、『この効果で特殊召喚したモンスターのレベルは１つ上がり、攻撃力・守備力は１００ポイントアップする』効果の適用はなくなります。\n（レベル・攻撃力・守備力は元に戻ります。なお、「{{霞の谷のファルコン|8109}}」自身はフィールドに残りますので、その攻撃は通常通り行われます。）', '強化蘇生10983ノ効果ニヨッテ霞ノ谷ノファルコン8109ヲ特殊召喚シテイマスnnソノ後ニ強化蘇生10983ヲ手札ニ戻シテソノ霞ノ谷ノファルコン8109デ攻撃宣言シタ場合霞ノ谷ノファルコン8109ノレベル攻撃力守備力ハドウナリマスカnマタソノ攻撃ハドウナリマスカ', '強化蘇生10983ガフィールドカラ離レタ場合特殊召喚サレテイル霞ノ谷ノファルコン8109ハ強化蘇生10983ノ対象カラ外レルタメコノ効果デ特殊召喚シタモンスターノレベルハ1ツ上ガリ攻撃力守備力ハ100ポイントアップスル効果ノ適用ハナクナリマスnレベル攻撃力守備力ハ元ニ戻リマスナオ霞ノ谷ノファルコン8109自身ハフィールドニ残リマスノデソノ攻撃ハ通常通リ行ワレマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (175, '6053', '3枚の「{{7|6053}}」が自分の魔法＆罠ゾーンに揃った際の『「{{7|6053}}」が自分フィールド上に表側表示で３枚揃った時、自分はデッキからカードを３枚ドローする。その後全ての「{{7|6053}}」を破壊する』効果の発動にチェーンして「{{サイクロン|4909}}」が発動し、「{{7|6053}}」が破壊された場合、処理はどうなりますか？', '『自分はデッキからカードを３枚ドローする』効果を発動した「{{7|6053}}」がその「{{サイクロン|4909}}」で破壊された場合には、『自分フィールド上に表側表示で３枚揃った時、自分はデッキからカードを３枚ドローする。その後全ての「{{7|6053}}」を破壊する』処理は適用されません。\n（その場合、「{{サイクロン|4909}}」で破壊され墓地へ送られた1枚の「{{7|6053}}」の『このカードがフィールドから墓地へ送られた時、自分は７００ライフポイント回復する』効果が発動し、処理が行われる事になります。）\n\nなお、『自分はデッキからカードを３枚ドローする』効果を発動していない残り2枚の「{{7|6053}}」のどちらかが「{{サイクロン|4909}}」によって破壊されたとしても処理は通常通り行われます。\n（『「{{7|6053}}」が自分フィールド上に表側表示で３枚揃った時、自分はデッキからカードを３枚ドローする。その後全ての「{{7|6053}}」を破壊する』処理は通常通り行われ、墓地へ送られた3枚の「{{7|6053}}」の『このカードがフィールドから墓地へ送られた時、自分は７００ライフポイント回復する』効果がチェーンにて発動する事になります。）', '3枚ノ76053ガ自分ノ魔法罠ゾーンニ揃ッタ際ノ76053ガ自分フィールド上ニ表側表示デ3枚揃ッタ時自分ハデッキカラカードヲ3枚ドロースルソノ後全テノ76053ヲ破壊スル効果ノ発動ニチェーンシテサイクロン4909ガ発動シ76053ガ破壊サレタ場合処理ハドウナリマスカ', '自分ハデッキカラカードヲ3枚ドロースル効果ヲ発動シタ76053ガソノサイクロン4909デ破壊サレタ場合ニハ自分フィールド上ニ表側表示デ3枚揃ッタ時自分ハデッキカラカードヲ3枚ドロースルソノ後全テノ76053ヲ破壊スル処理ハ適用サレマセンnソノ場合サイクロン4909デ破壊サレ墓地ヘ送ラレタ1枚ノ76053ノコノカードガフィールドカラ墓地ヘ送ラレタ時自分ハ700ライフポイント回復スル効果ガ発動シ処理ガ行ワレル事ニナリマスnnナオ自分ハデッキカラカードヲ3枚ドロースル効果ヲ発動シテイナイ残リ2枚ノ76053ノドチラカガサイクロン4909ニヨッテ破壊サレタトシテモ処理ハ通常通リ行ワレマスn76053ガ自分フィールド上ニ表側表示デ3枚揃ッタ時自分ハデッキカラカードヲ3枚ドロースルソノ後全テノ76053ヲ破壊スル処理ハ通常通リ行ワレ墓地ヘ送ラレタ3枚ノ76053ノコノカードガフィールドカラ墓地ヘ送ラレタ時自分ハ700ライフポイント回復スル効果ガチェーンニテ発動スル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (174, '4861', '「{{神の宣告|4861}}」でモンスターの召喚が無効になり破壊された場合、「{{補給部隊|11147}}」の効果は発動しますか？', '「{{神の宣告|4861}}」で召喚が無効になり破壊されたモンスターはフィールドのカードの扱いではありません。\n\n『自分フィールドのモンスターが戦闘・効果で破壊された』扱いではありませんので、「{{補給部隊|11147}}」の効果は発動しません。', '神ノ宣告4861デモンスターノ召喚ガ無効ニナリ破壊サレタ場合補給部隊11147ノ効果ハ発動シマスカ', '神ノ宣告4861デ召喚ガ無効ニナリ破壊サレタモンスターハフィールドノカードノ扱イデハアリマセンnn自分フィールドノモンスターガ戦闘効果デ破壊サレタ扱イデハアリマセンノデ補給部隊11147ノ効果ハ発動シマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (172, '9241', '自分のメインフェイズ１にて「{{シンクロ・マテリアル|9241}}」を発動しました。\n\nその対象のなったモンスターがその後にフィールドに存在しなくなった場合や、そのモンスターをシンクロ素材に使用しなかった場合、自分はバトルフェイズを行う事はできますか？', '自分が「{{シンクロ・マテリアル|9241}}」を発動した場合には、『このカードを発動するターン、自分はバトルフェイズを行う事ができない』によって、バトルフェイズを行う事はできません。\n\n「{{シンクロ・マテリアル|9241}}」の発動後にその対象となったモンスターがフィールドに存在しなくなる等によって、その対象のモンスターを素材としてシンクロ召喚を行えなかったとしても、自分はバトルフェイズを行う事はできません。', '自分ノメインフェイズ1ニテシンクロマテリアル9241ヲ発動シマシタnnソノ対象ノナッタモンスターガソノ後ニフィールドニ存在シナクナッタ場合ヤソノモンスターヲシンクロ素材ニ使用シナカッタ場合自分ハバトルフェイズヲ行ウ事ハデキマスカ', '自分ガシンクロマテリアル9241ヲ発動シタ場合ニハコノカードヲ発動スルターン自分ハバトルフェイズヲ行ウ事ガデキナイニヨッテバトルフェイズヲ行ウ事ハデキマセンnnシンクロマテリアル9241ノ発動後ニソノ対象トナッタモンスターガフィールドニ存在シナクナル等ニヨッテソノ対象ノモンスターヲ素材トシテシンクロ召喚ヲ行エナカッタトシテモ自分ハバトルフェイズヲ行ウ事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (171, '5752', '「{{ディメンション・マジック|5752}}」の発動にチェーンして、「{{虚無空間|9153}}」が発動され、特殊召喚が行えなくなった場合、「{{ディメンション・マジック|5752}}」の効果処理はどうなりますか？', '質問の状況の場合、「{{ディメンション・マジック|5752}}」の処理は『選択した自分のモンスターをリリースし』の処理のみを行う事になります。\n（手札から魔法使い族モンスターは特殊召喚されず、フィールドのモンスターを選んで破壊する処理も行いません。）', 'ディメンションマジック5752ノ発動ニチェーンシテ虚無空間9153ガ発動サレ特殊召喚ガ行エナクナッタ場合ディメンションマジック5752ノ効果処理ハドウナリマスカ', '質問ノ状況ノ場合ディメンションマジック5752ノ処理ハ選択シタ自分ノモンスターヲリリースシノ処理ノミヲ行ウ事ニナリマスn手札カラ魔法使イ族モンスターハ特殊召喚サレズフィールドノモンスターヲ選ンデ破壊スル処理モ行イマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (170, '5740', '相手の発動した「{{スキルドレイン|5740}}」が表側表示で存在しています。\n\nこの状況で、自分の墓地の存在する「{{BF－精鋭のゼピュロス|9244}}」の『①：このカードが墓地に存在する場合、自分フィールドの表側表示のカード１枚を持ち主の手札に戻して発動できる。このカードを墓地から特殊召喚し、自分は４００ダメージを受ける』効果を発動した場合、『自分は４００ダメージを受ける』処理は無効化されますか？', '「{{BF－精鋭のゼピュロス|9244}}」の効果は墓地にて発動し、処理が行われる効果ですので、「{{スキルドレイン|5740}}」の効果によって無効化される事はありません。\n（『自分は４００ダメージを受ける』処理も通常通り適用されます。）', '相手ノ発動シタスキルドレイン5740ガ表側表示デ存在シテイマスnnコノ状況デ自分ノ墓地ノ存在スルbf精鋭ノゼピュロス9244ノ①コノカードガ墓地ニ存在スル場合自分フィールドノ表側表示ノカード1枚ヲ持チ主ノ手札ニ戻シテ発動デキルコノカードヲ墓地カラ特殊召喚シ自分ハ400ダメージヲ受ケル効果ヲ発動シタ場合自分ハ400ダメージヲ受ケル処理ハ無効化サレマスカ', 'bf精鋭ノゼピュロス9244ノ効果ハ墓地ニテ発動シ処理ガ行ワレル効果デスノデスキルドレイン5740ノ効果ニヨッテ無効化サレル事ハアリマセンn自分ハ400ダメージヲ受ケル処理モ通常通リ適用サレマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (169, '7341', '自分フィールドにもう1度召喚され効果を得ている状態の「{{炎妖蝶ウィルプス|7341}}」と、通常モンスター扱いの「{{ギガプラント|7427}}」が表側表示で存在しています。\n\nこの状況で「{{フォース・リリース|7455}}」を発動した場合、その効果は「{{炎妖蝶ウィルプス|7341}}」と「{{ギガプラント|7427}}」の両方に適用されますか？', '質問の状況の場合、既にもう１度召喚され効果を得ている状態の「{{炎妖蝶ウィルプス|7341}}」には、「{{フォース・リリース|7455}}」の効果は適用されません。\n\nしたがって、通常モンスター扱いであった「{{ギガプラント|7427}}」のみが『このカードの発動時に自分フィールド上に表側表示で存在する全てのデュアルモンスターは再度召喚した状態になる』効果を受けて、『この効果を適用したモンスターはエンドフェイズ時に裏側守備表示になる』処理も適用される事になります。', '自分フィールドニモウ1度召喚サレ効果ヲ得テイル状態ノ炎妖蝶ウィルプス7341ト通常モンスター扱イノギガプラント7427ガ表側表示デ存在シテイマスnnコノ状況デフォースリリース7455ヲ発動シタ場合ソノ効果ハ炎妖蝶ウィルプス7341トギガプラント7427ノ両方ニ適用サレマスカ', '質問ノ状況ノ場合既ニモウ1度召喚サレ効果ヲ得テイル状態ノ炎妖蝶ウィルプス7341ニハフォースリリース7455ノ効果ハ適用サレマセンnnシタガッテ通常モンスター扱イデアッタギガプラント7427ノミガコノカードノ発動時ニ自分フィールド上ニ表側表示デ存在スル全テノデュアルモンスターハ再度召喚シタ状態ニナル効果ヲ受ケテコノ効果ヲ適用シタモンスターハエンドフェイズ時ニ裏側守備表示ニナル処理モ適用サレル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (168, '7247', '相手ターンに、自分の「{{デコイドラゴン|7247}}」が相手モンスターの攻撃対象になり、「{{デコイドラゴン|7247}}」の効果が発動しました。\n\nその発動した効果にチェーンして自分の墓地に存在する「{{超電磁タートル|11120}}」の効果を発動した場合、それぞれの効果の処理はどうなりますか？', '質問の状況の場合、チェーンして発動した「{{超電磁タートル|11120}}」の効果処理によって、「{{デコイドラゴン|7247}}」の効果処理時点では、エンドステップを迎えています。\n\nこの場合、選択した墓地のドラゴン族モンスターを特殊召喚する処理は行いますが、攻撃は終了していますので、ダメージ計算は行いません。', '相手ターンニ自分ノデコイドラゴン7247ガ相手モンスターノ攻撃対象ニナリデコイドラゴン7247ノ効果ガ発動シマシタnnソノ発動シタ効果ニチェーンシテ自分ノ墓地ニ存在スル超電磁タートル11120ノ効果ヲ発動シタ場合ソレゾレノ効果ノ処理ハドウナリマスカ', '質問ノ状況ノ場合チェーンシテ発動シタ超電磁タートル11120ノ効果処理ニヨッテデコイドラゴン7247ノ効果処理時点デハエンドステップヲ迎エテイマスnnコノ場合選択シタ墓地ノドラゴン族モンスターヲ特殊召喚スル処理ハ行イマスガ攻撃ハ終了シテイマスノデダメージ計算ハ行イマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (167, '10326', '「{{ティマイオスの眼|10326}}」の効果で融合召喚した「{{呪符竜|10325}}」を対象として「{{融合解除|5118}}」を発動した場合、処理はどうなりますか？', '『その融合モンスターを持ち主のEXデッキに戻す』処理によって「{{呪符竜|10325}}」は元々の持ち主のエクストラデッキに戻りますが、『「{{ブラック・マジシャン|4041}}」＋ドラゴン族モンスター』の融合素材一組を使用していませんので、『その後、EXデッキに戻したそのモンスターの融合召喚に使用した融合素材モンスター一組が自分の墓地に揃っていれば、その一組を自分フィールドに特殊召喚できる』処理は行われません。\n\n「{{ティマイオスの眼光|21612}}」の効果で特殊召喚した「{{呪符竜|10325}}」を対象として「{{融合解除|5118}}」を発動した場合も同様です。', 'ティマイオスノ眼10326ノ効果デ融合召喚シタ呪符龍10325ヲ対象トシテ融合解除5118ヲ発動シタ場合処理ハドウナリマスカ', 'ソノ融合モンスターヲ持チ主ノexデッキニ戻ス処理ニヨッテ呪符龍10325ハ元々ノ持チ主ノエクストラデッキニ戻リマスガブラックマジシャン4041ドラゴン族モンスターノ融合素材一組ヲ使用シテイマセンノデソノ後exデッキニ戻シタソノモンスターノ融合召喚ニ使用シタ融合素材モンスター一組ガ自分ノ墓地ニ揃ッテイレバソノ一組ヲ自分フィールドニ特殊召喚デキル処理ハ行ワレマセンnnティマイオスノ眼光21612ノ効果デ特殊召喚シタ呪符龍10325ヲ対象トシテ融合解除5118ヲ発動シタ場合モ同様デス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (166, '10200', '「{{マドルチェ・マナー|10200}}」を発動する際に、自分の墓地に存在する「{{クイーンマドルチェ・ティアラミス|10270}}」を対象として選択する事はできますか？\n\nまた、「{{マドルチェ・マナー|10200}}」の効果処理にて、『その後、自分の墓地のモンスター1体を選んでデッキに戻す事ができる』処理を行う場合、自分の墓地に存在する「{{クイーンマドルチェ・ティアラミス|10270}}」を選ぶ事はできますか？', '「{{マドルチェ・マナー|10200}}」を発動する際に対象として選択する『自分の墓地の「マドルチェ」と名のついたモンスター1体』として、自分の墓地に存在する「{{クイーンマドルチェ・ティアラミス|10270}}」を選択する事はできます。\nその場合でも、「{{マドルチェ・マナー|10200}}」の効果処理は通常通り適用されます。なお、対象として選択された「{{クイーンマドルチェ・ティアラミス|10270}}」は、エクストラデッキへ戻ります。\n\nまた、「{{マドルチェ・マナー|10200}}」の効果処理にて、『その後、自分の墓地のモンスター1体を選んでデッキに戻す事ができる』処理を行う場合、自分の墓地に存在する「{{クイーンマドルチェ・ティアラミス|10270}}」を選ぶ事もできます。その場合、その「{{クイーンマドルチェ・ティアラミス|10270}}」は、エクストラデッキへ戻ります。', 'マドルチェマナー10200ヲ発動スル際ニ自分ノ墓地ニ存在スルクイーンマドルチェティアラミス10270ヲ対象トシテ選択スル事ハデキマスカnnマタマドルチェマナー10200ノ効果処理ニテソノ後自分ノ墓地ノモンスター1体ヲ選ンデデッキニ戻ス事ガデキル処理ヲ行ウ場合自分ノ墓地ニ存在スルクイーンマドルチェティアラミス10270ヲ選ブ事ハデキマスカ', 'マドルチェマナー10200ヲ発動スル際ニ対象トシテ選択スル自分ノ墓地ノマドルチェト名ノツイタモンスター1体トシテ自分ノ墓地ニ存在スルクイーンマドルチェティアラミス10270ヲ選択スル事ハデキマスnソノ場合デモマドルチェマナー10200ノ効果処理ハ通常通リ適用サレマスナオ対象トシテ選択サレタクイーンマドルチェティアラミス10270ハエクストラデッキヘ戻リマスnnマタマドルチェマナー10200ノ効果処理ニテソノ後自分ノ墓地ノモンスター1体ヲ選ンデデッキニ戻ス事ガデキル処理ヲ行ウ場合自分ノ墓地ニ存在スルクイーンマドルチェティアラミス10270ヲ選ブ事モデキマスソノ場合ソノクイーンマドルチェティアラミス10270ハエクストラデッキヘ戻リマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (165, '6512', 'フィールドの裏側表示のカード１枚を対象として発動する「{{暗黒界の雷|6512}}」にチェーンして「{{アヌビスの裁き|5232}}」を発動する事はできますか？', 'モンスターゾーンに裏側守備表示で存在するモンスターを対象として「{{暗黒界の雷|6512}}」が発動された際には、チェーンして「{{アヌビスの裁き|5232}}」を発動する事はできません。\n\nフィールドゾーンや魔法＆罠ゾーンに裏側表示で存在するカードを対象として、「{{暗黒界の雷|6512}}」が発動された際には、チェーンして「{{アヌビスの裁き|5232}}」を発動する事ができます。', 'フィールドノ裏側表示ノカード1枚ヲ対象トシテ発動スル暗黒界ノ雷6512ニチェーンシテアヌビスノ裁キ5232ヲ発動スル事ハデキマスカ', 'モンスターゾーンニ裏側守備表示デ存在スルモンスターヲ対象トシテ暗黒界ノ雷6512ガ発動サレタ際ニハチェーンシテアヌビスノ裁キ5232ヲ発動スル事ハデキマセンnnフィールドゾーンヤ魔法罠ゾーンニ裏側表示デ存在スルカードヲ対象トシテ暗黒界ノ雷6512ガ発動サレタ際ニハチェーンシテアヌビスノ裁キ5232ヲ発動スル事ガデキマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (164, '10437', '「{{ブレイクスルー・スキル|10437}}」の発動にチェーンして「{{エネミーコントローラー|5505}}」が発動し、「{{ブレイクスルー・スキル|10437}}」の対象に選択された相手フィールドのモンスターのコントロールが効果処理時に自分に移っている場合、効果は適用されますか？', '「{{ブレイクスルー・スキル|10437}}」の対象に選択したモンスターのコントロールが、効果処理時に相手から自分へと移っている場合、「{{ブレイクスルー・スキル|10437}}」の効果は適用されません。\n（「{{ブレイクスルー・スキル|10437}}」がフィールドにて発動した場合、墓地の自身を除外して効果を発動した場合、どちらの場合も同様の処理となります。）', 'ブレイクスルースキル10437ノ発動ニチェーンシテエネミーコントローラー5505ガ発動シブレイクスルースキル10437ノ対象ニ選択サレタ相手フィールドノモンスターノコントロールガ効果処理時ニ自分ニ移ッテイル場合効果ハ適用サレマスカ', 'ブレイクスルースキル10437ノ対象ニ選択シタモンスターノコントロールガ効果処理時ニ相手カラ自分ヘト移ッテイル場合ブレイクスルースキル10437ノ効果ハ適用サレマセンnブレイクスルースキル10437ガフィールドニテ発動シタ場合墓地ノ自身ヲ除外シテ効果ヲ発動シタ場合ドチラノ場合モ同様ノ処理トナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (162, '14023', '自分が「{{プランキッズ・ロケット|14023}}」の『①：このカードが融合召喚に成功した場合に発動できる。このターンこのカードは、攻撃力が１０００ダウンし、さらに直接攻撃もできる』モンスター効果を発動しているターンです。\n\nその後、そのターン中に、「{{スキルドレイン|5740}}」が発動し、その「{{プランキッズ・ロケット|14023}}」のモンスター効果が無効化された場合、適用されている効果はどうなりますか？', '「{{プランキッズ・ロケット|14023}}」のモンスター効果の適用後に、「{{スキルドレイン|5740}}」の『①：このカードが魔法＆罠ゾーンに存在する限り、フィールドの全ての表側表示モンスターの効果は無効化される』効果によって、「{{プランキッズ・ロケット|14023}}」のモンスター効果が無効化された場合には、ダウンしていた攻撃力は元に戻りますが、このターンに直接攻撃が行える状態のままとなります。', '自分ガプランキッズロケット14023ノ①コノカードガ融合召喚ニ成功シタ場合ニ発動デキルコノターンコノカードハ攻撃力ガ1000ダウンシサラニ直接攻撃モデキルモンスター効果ヲ発動シテイルターンデスnnソノ後ソノターン中ニスキルドレイン5740ガ発動シソノプランキッズロケット14023ノモンスター効果ガ無効化サレタ場合適用サレテイル効果ハドウナリマスカ', 'プランキッズロケット14023ノモンスター効果ノ適用後ニスキルドレイン5740ノ①コノカードガ魔法罠ゾーンニ存在スル限リフィールドノ全テノ表側表示モンスターノ効果ハ無効化サレル効果ニヨッテプランキッズロケット14023ノモンスター効果ガ無効化サレタ場合ニハダウンシテイタ攻撃力ハ元ニ戻リマスガコノターンニ直接攻撃ガ行エル状態ノママトナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (161, '6054', '自分フィールドに表側表示で存在している、「{{レベル制限B地区|6054}}」等の永続魔法カードを、プレイヤーが自分の意思で墓地へ送る事はできますか？\n\nまた、自分フィールドに表側表示で存在している、「{{王宮のお触れ|4866}}」等の永続罠カードを、プレイヤーが自分の意思で墓地へ送る事はできますか？', '永続魔法カードや永続罠カードは、基本的に破壊されるまでフィールドに残り続けます。\n\n何らかの効果を使用する事なく、プレイヤーの意思で勝手に墓地へ送る事はできません。', '自分フィールドニ表側表示デ存在シテイルレベル制限b地区6054等ノ永続魔法カードヲプレイヤーガ自分ノ意思デ墓地ヘ送ル事ハデキマスカnnマタ自分フィールドニ表側表示デ存在シテイル王宮ノオ触レ4866等ノ永続罠カードヲプレイヤーガ自分ノ意思デ墓地ヘ送ル事ハデキマスカ', '永続魔法カードヤ永続罠カードハ基本的ニ破壊サレルマデフィールドニ残リ続ケマスnn何ラカノ効果ヲ使用スル事ナクプレイヤーノ意思デ勝手ニ墓地ヘ送ル事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (160, '7136', '「{{義賊の極意書|7136}}」の対象となっている「{{海賊船スカルブラッド号|5143}}」がそのターンに発動した「{{月読命|5780}}」の効果によって裏側守備表示になりました。\n\nそのターンに反転召喚したその「{{海賊船スカルブラッド号|5143}}」が、相手モンスターを攻撃し戦闘ダメージを与えた場合、「{{義賊の極意書|7136}}」の『相手の手札をランダムに２枚捨てる』効果は適用されますか？', '「{{義賊の極意書|7136}}」の対象となったモンスターがその後に裏側守備表示になった場合には、そのターンにて再び表側表示に戻り、相手に戦闘ダメージを与えたとしても、『相手の手札をランダムに２枚捨てる』効果は適用されません。', '義賊ノ極意書7136ノ対象トナッテイル海賊船スカルブラッド号5143ガソノターンニ発動シタ月読命5780ノ効果ニヨッテ裏側守備表示ニナリマシタnnソノターンニ反転召喚シタソノ海賊船スカルブラッド号5143ガ相手モンスターヲ攻撃シ戦闘ダメージヲ与エタ場合義賊ノ極意書7136ノ相手ノ手札ヲランダムニ2枚捨テル効果ハ適用サレマスカ', '義賊ノ極意書7136ノ対象トナッタモンスターガソノ後ニ裏側守備表示ニナッタ場合ニハソノターンニテ再ビ表側表示ニ戻リ相手ニ戦闘ダメージヲ与エタトシテモ相手ノ手札ヲランダムニ2枚捨テル効果ハ適用サレマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (159, '9153', '「{{虚無空間|9153}}」の適用中に、自分フィールドの「{{キラー・トマト|4930}}」が戦闘によって破壊され墓地へ送られました。\n\nこの場合、「{{虚無空間|9153}}」の『デッキまたはフィールド上から自分の墓地へカードが送られた時、このカードを破壊する』効果が発動しますが、チェーンして「{{キラー・トマト|4930}}」の効果を発動する事はできますか？', '質問の状況の場合、「{{虚無空間|9153}}」の『このカードがフィールド上に存在する限り、お互いにモンスターを特殊召喚できない』効果が適用されている状態にて、『デッキまたはフィールド上から自分の墓地へカードが送られた時、このカードを破壊する』効果が発動しています。\n\nしたがって、「{{虚無空間|9153}}」の効果が発動した時点では、お互いにモンスターを特殊召喚できませんので、「{{キラー・トマト|4930}}」の効果を発動する事はできません。', '虚無空間9153ノ適用中ニ自分フィールドノキラートマト4930ガ戦闘ニヨッテ破壊サレ墓地ヘ送ラレマシタnnコノ場合虚無空間9153ノデッキマタハフィールド上カラ自分ノ墓地ヘカードガ送ラレタ時コノカードヲ破壊スル効果ガ発動シマスガチェーンシテキラートマト4930ノ効果ヲ発動スル事ハデキマスカ', '質問ノ状況ノ場合虚無空間9153ノコノカードガフィールド上ニ存在スル限リオ互イニモンスターヲ特殊召喚デキナイ効果ガ適用サレテイル状態ニテデッキマタハフィールド上カラ自分ノ墓地ヘカードガ送ラレタ時コノカードヲ破壊スル効果ガ発動シテイマスnnシタガッテ虚無空間9153ノ効果ガ発動シタ時点デハオ互イニモンスターヲ特殊召喚デキマセンノデキラートマト4930ノ効果ヲ発動スル事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (158, '4908', '「{{魔力の枷|4908}}」の適用中に、手札から２体のモンスターとエクストラデッキから１体のモンスターをペンデュラム召喚します。  この場合、払わなければならないライフポイントはいくつですか？', '「{{魔力の枷|4908}}」が適用されている場合、手札からモンスターを召喚・特殊召喚する際に、１体につき５００のライフポイントを払う必要があります。\n\nしたがって、質問の状況の場合、手札から２体のモンスターをペンデュラム召喚しようとしていますので、先に１０００のライフポイントを払ってから、ペンデュラム召喚を行う事になります。 (エクストラデッキからペンデュラム召喚するモンスターの分のライフポイントを払う必要はありません。)', '魔力ノ枷4908ノ適用中ニ手札カラ2体ノモンスタートエクストラデッキカラ1体ノモンスターヲペンデュラム召喚シマスコノ場合払ワナケレバナラナイライフポイントハイクツデスカ', '魔力ノ枷4908ガ適用サレテイル場合手札カラモンスターヲ召喚特殊召喚スル際ニ1体ニツキ500ノライフポイントヲ払ウ必要ガアリマスnnシタガッテ質問ノ状況ノ場合手札カラ2体ノモンスターヲペンデュラム召喚シヨウトシテイマスノデ先ニ1000ノライフポイントヲ払ッテカラペンデュラム召喚ヲ行ウ事ニナリマスエクストラデッキカラペンデュラム召喚スルモンスターノ分ノライフポイントヲ払ウ必要ハアリマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (157, '8579', '「{{ガントレット・ウォリアー|8579}}」が相手モンスターと戦闘を行っているダメージステップにて、『このカードをリリースして発動する。自分フィールド上に表側表示で存在する全ての戦士族モンスターの攻撃力・守備力は５００ポイントアップし、そのモンスターが戦闘を行ったダメージステップ終了時まで適用される。この効果は相手ターンでも発動する事ができる』効果を発動する事はできますか？', '「{{ガントレット・ウォリアー|8579}}」自身が相手モンスターと戦闘を行っている場合でも、ダメージステップ開始時やダメージ計算前に、「{{ガントレット・ウォリアー|8579}}」自身をリリースし、効果を発動する事はできます。\n\nその場合、その戦闘ではダメージ計算は行われず、ダメージステップが終了する事になります。 \n\nただし、自分フィールドのモンスターが「{{ガントレット・ウォリアー|8579}}」のみの場合には、「{{ガントレット・ウォリアー|8579}}」の効果を発動する事はできません。', 'ガントレットウォリアー8579ガ相手モンスタート戦闘ヲ行ッテイルダメージステップニテコノカードヲリリースシテ発動スル自分フィールド上ニ表側表示デ存在スル全テノ戦士族モンスターノ攻撃力守備力ハ500ポイントアップシソノモンスターガ戦闘ヲ行ッタダメージステップ終了時マデ適用サレルコノ効果ハ相手ターンデモ発動スル事ガデキル効果ヲ発動スル事ハデキマスカ', 'ガントレットウォリアー8579自身ガ相手モンスタート戦闘ヲ行ッテイル場合デモダメージステップ開始時ヤダメージ計算前ニガントレットウォリアー8579自身ヲリリースシ効果ヲ発動スル事ハデキマスnnソノ場合ソノ戦闘デハダメージ計算ハ行ワレズダメージステップガ終了スル事ニナリマスnnタダシ自分フィールドノモンスターガガントレットウォリアー8579ノミノ場合ニハガントレットウォリアー8579ノ効果ヲ発動スル事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (155, '11382', '相手の「{{始祖竜ワイアーム|11382}}」の攻撃宣言時に、自分は「{{コズミック・ブレイザー・ドラゴン|12998}}」の『●相手モンスターの攻撃宣言時に発動できる。その攻撃を無効にし、その後バトルフェイズを終了する』モンスター効果を発動しました。\n\nこの場合、処理はどうなりますか？', '質問の状況の場合、相手の「{{始祖竜ワイアーム|11382}}」は『②：このカードがモンスターゾーンに存在する限り、このカードは通常モンスター以外のモンスターとの戦闘では破壊されず、このカード以外のモンスターの効果を受けない』モンスター効果を持つモンスターですので、「{{コズミック・ブレイザー・ドラゴン|12998}}」のモンスター効果によって、その攻撃は無効にならず、『その後バトルフェイズを終了する』処理は適用されません。\n（この場合、戦闘の巻き戻しが発生します。）\n\nなお、この場合でも、そのターンのエンドフェイズに「{{コズミック・ブレイザー・ドラゴン|12998}}」をモンスターゾーンに戻す処理は通常通り適用されます。', '相手ノ始祖龍ワイアーム11382ノ攻撃宣言時ニ自分ハコズミックブレイザードラゴン12998ノ●相手モンスターノ攻撃宣言時ニ発動デキルソノ攻撃ヲ無効ニシソノ後バトルフェイズヲ終了スルモンスター効果ヲ発動シマシタnnコノ場合処理ハドウナリマスカ', '質問ノ状況ノ場合相手ノ始祖龍ワイアーム11382ハ②コノカードガモンスターゾーンニ存在スル限リコノカードハ通常モンスター以外ノモンスタートノ戦闘デハ破壊サレズコノカード以外ノモンスターノ効果ヲ受ケナイモンスター効果ヲ持ツモンスターデスノデコズミックブレイザードラゴン12998ノモンスター効果ニヨッテソノ攻撃ハ無効ニナラズソノ後バトルフェイズヲ終了スル処理ハ適用サレマセンnコノ場合戦闘ノ巻キ戻シガ発生シマスnnナオコノ場合デモソノターンノエンドフェイズニコズミックブレイザードラゴン12998ヲモンスターゾーンニ戻ス処理ハ通常通リ適用サレマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (154, '11217', '「{{EMディスカバー・ヒッポ|11217}}」の『自分は通常召喚に加えて１度だけ、自分メインフェイズに、レベル７以上のモンスター１体を表側攻撃表示でアドバンス召喚できる』効果を適用する際に、「{{死皇帝の陵墓|6759}}」の効果を発動する事はできますか？\n\nまた、「{{EMディスカバー・ヒッポ|11217}}」の『自分は通常召喚に加えて１度だけ、自分メインフェイズに、レベル７以上のモンスター１体を表側攻撃表示でアドバンス召喚できる』効果を適用する際に、「{{神獣王バルバロス|7346}}」をリリースなしで召喚する事はできますか？', '「{{EMディスカバー・ヒッポ|11217}}」の『自分は通常召喚に加えて１度だけ、自分メインフェイズに、レベル７以上のモンスター１体を表側攻撃表示でアドバンス召喚できる』効果を適用する場合、必ずリリースを行う必要があります。\n\n「{{死皇帝の陵墓|6759}}」の『アドバンス召喚に必要なモンスターの数×１０００ライフポイントを払う事で、リリースなしでそのモンスターを通常召喚できる』効果を適用して、リリースを行わずに召喚したり、「{{神獣王バルバロス|7346}}」をリリースなしで召喚させる事はできません。', 'emディスカバーヒッポ11217ノ自分ハ通常召喚ニ加エテ1度ダケ自分メインフェイズニレベル7以上ノモンスター1体ヲ表側攻撃表示デアドバンス召喚デキル効果ヲ適用スル際ニ死皇帝ノ陵墓6759ノ効果ヲ発動スル事ハデキマスカnnマタemディスカバーヒッポ11217ノ自分ハ通常召喚ニ加エテ1度ダケ自分メインフェイズニレベル7以上ノモンスター1体ヲ表側攻撃表示デアドバンス召喚デキル効果ヲ適用スル際ニ神獣王バルバロス7346ヲリリースナシデ召喚スル事ハデキマスカ', 'emディスカバーヒッポ11217ノ自分ハ通常召喚ニ加エテ1度ダケ自分メインフェイズニレベル7以上ノモンスター1体ヲ表側攻撃表示デアドバンス召喚デキル効果ヲ適用スル場合必ズリリースヲ行ウ必要ガアリマスnn死皇帝ノ陵墓6759ノアドバンス召喚ニ必要ナモンスターノ数×1000ライフポイントヲ払ウ事デリリースナシデソノモンスターヲ通常召喚デキル効果ヲ適用シテリリースヲ行ワズニ召喚シタリ神獣王バルバロス7346ヲリリースナシデ召喚サセル事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (153, '10725', '「{{ストイック・チャレンジ|10725}}」を装備しているエクシーズモンスターが「{{月の書|5432}}」の効果によって裏側守備表示になりました。\n\nこの場合、「{{ストイック・チャレンジ|10725}}」の『このカードがフィールド上から離れた時、装備モンスターを破壊する』処理はどうなりますか？', '質問の状況のように、「{{ストイック・チャレンジ|10725}}」の装備モンスターが裏側守備表示になった場合、裏側守備表示のモンスターは装備魔法カードを装備する対象として適切ではなくなりますので、「{{ストイック・チャレンジ|10725}}」が破壊される事になります。\n\nその場合、裏側守備表示となったエクシーズモンスターは「{{ストイック・チャレンジ|10725}}」が破壊される際には、「{{ストイック・チャレンジ|10725}}」の装備モンスターの扱いではなくなっていますので、『このカードがフィールド上から離れた時、装備モンスターを破壊する』処理は適用されません。', 'ストイックチャレンジ10725ヲ装備シテイルエクシーズモンスターガ月ノ書5432ノ効果ニヨッテ裏側守備表示ニナリマシタnnコノ場合ストイックチャレンジ10725ノコノカードガフィールド上カラ離レタ時装備モンスターヲ破壊スル処理ハドウナリマスカ', '質問ノ状況ノヨウニストイックチャレンジ10725ノ装備モンスターガ裏側守備表示ニナッタ場合裏側守備表示ノモンスターハ装備魔法カードヲ装備スル対象トシテ適切デハナクナリマスノデストイックチャレンジ10725ガ破壊サレル事ニナリマスnnソノ場合裏側守備表示トナッタエクシーズモンスターハストイックチャレンジ10725ガ破壊サレル際ニハストイックチャレンジ10725ノ装備モンスターノ扱イデハナクナッテイマスノデコノカードガフィールド上カラ離レタ時装備モンスターヲ破壊スル処理ハ適用サレマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (152, '11018', '相手のモンスターゾーンに表側攻撃表示のモンスターしか存在しない場合、「{{No.13 ケインズ・デビル|11018}}」や「{{No.31 アベルズ・デビル|11019}}」の『１ターンに１度、このカードのエクシーズ素材を１つ取り除いて発動できる。相手フィールド上のモンスターは、全て表側攻撃表示になり、このターン攻撃可能な場合このカードを攻撃しなければならない』効果を発動する事はできますか？', '相手のモンスターゾーンに存在するモンスターが、全て表側攻撃表示のモンスターである場合でも、「{{No.13 ケインズ・デビル|11018}}」や「{{No.31 アベルズ・デビル|11019}}」の効果を発動する事はできます。\n\n効果を発動した場合、既に表側攻撃表示で存在していたモンスター及び、その「{{No.13 ケインズ・デビル|11018}}」や「{{No.31 アベルズ・デビル|11019}}」の効果処理によって表側攻撃表示になったモンスターに、『このターン攻撃可能な場合このカードを攻撃しなければならない』効果が適用される事になります。', '相手ノモンスターゾーンニ表側攻撃表示ノモンスターシカ存在シナイ場合no.13ケインズデビル11018ヤno.31アベルズデビル11019ノ1ターンニ1度コノカードノエクシーズ素材ヲ1ツ取リ除イテ発動デキル相手フィールド上ノモンスターハ全テ表側攻撃表示ニナリコノターン攻撃可能ナ場合コノカードヲ攻撃シナケレバナラナイ効果ヲ発動スル事ハデキマスカ', '相手ノモンスターゾーンニ存在スルモンスターガ全テ表側攻撃表示ノモンスターデアル場合デモno.13ケインズデビル11018ヤno.31アベルズデビル11019ノ効果ヲ発動スル事ハデキマスnn効果ヲ発動シタ場合既ニ表側攻撃表示デ存在シテイタモンスター及ビソノno.13ケインズデビル11018ヤno.31アベルズデビル11019ノ効果処理ニヨッテ表側攻撃表示ニナッタモンスターニコノターン攻撃可能ナ場合コノカードヲ攻撃シナケレバナラナイ効果ガ適用サレル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (151, '10077', '直接攻撃を宣言しているモンスターを対象として、そのバトルステップやダメージステップに「{{蛮勇鱗粉|10077}}」を発動する事はできますか？', '相手プレイヤーへの直接攻撃を宣言している自分フィールドのモンスターを対象として、そのバトルステップやダメージステップに「{{蛮勇鱗粉|10077}}」を発動する事はできません。\n\nなお、バトルフェイズにて既に相手プレイヤーに直接攻撃を行った後のモンスターを対象として、「{{蛮勇鱗粉|10077}}」を発動する事はできます。', '直接攻撃ヲ宣言シテイルモンスターヲ対象トシテソノバトルステップヤダメージステップニ蛮勇鱗粉10077ヲ発動スル事ハデキマスカ', '相手プレイヤーヘノ直接攻撃ヲ宣言シテイル自分フィールドノモンスターヲ対象トシテソノバトルステップヤダメージステップニ蛮勇鱗粉10077ヲ発動スル事ハデキマセンnnナオバトルフェイズニテ既ニ相手プレイヤーニ直接攻撃ヲ行ッタ後ノモンスターヲ対象トシテ蛮勇鱗粉10077ヲ発動スル事ハデキマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (150, '10747', '相手の発動した「{{ゴーストリック・ランタン|10747}}」の『相手モンスターの直接攻撃宣言時、または自分フィールド上の「ゴーストリック」と名のついたモンスターが攻撃対象に選択された時に発動できる。その攻撃を無効にし、このカードを手札から裏側守備表示で特殊召喚する』効果によって、手札から裏側守備表示で「{{ゴーストリック・ランタン|10747}}」が特殊召喚された場合、自分は「{{時空の落とし穴|11288}}」を発動する事はできますか？', '相手が手札から「{{ゴーストリック・ランタン|10747}}」を裏側守備表示で特殊召喚した際に、自分は「{{時空の落とし穴|11288}}」を発動する事はできます。\n\nその場合、「{{時空の落とし穴|11288}}」の効果処理は通常通り適用されます。（その「{{ゴーストリック・ランタン|10747}}」は持ち主のデッキに戻り、自分は1000LPを失います。）', '相手ノ発動シタゴーストリックランタン10747ノ相手モンスターノ直接攻撃宣言時マタハ自分フィールド上ノゴーストリックト名ノツイタモンスターガ攻撃対象ニ選択サレタ時ニ発動デキルソノ攻撃ヲ無効ニシコノカードヲ手札カラ裏側守備表示デ特殊召喚スル効果ニヨッテ手札カラ裏側守備表示デゴーストリックランタン10747ガ特殊召喚サレタ場合自分ハ時空ノ落トシ穴11288ヲ発動スル事ハデキマスカ', '相手ガ手札カラゴーストリックランタン10747ヲ裏側守備表示デ特殊召喚シタ際ニ自分ハ時空ノ落トシ穴11288ヲ発動スル事ハデキマスnnソノ場合時空ノ落トシ穴11288ノ効果処理ハ通常通リ適用サレマスソノゴーストリックランタン10747ハ持チ主ノデッキニ戻リ自分ハ1000lpヲ失イマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (149, '5505', '相手のモンスターが、自分フィールドのモンスターに対して攻撃を行った時に、その攻撃対象となった自分フィールドのモンスターをリリースして、「{{エネミーコントローラー|5505}}」の『●自分フィールド上のモンスター１体をリリースして発動できる。相手フィールド上に表側表示で存在するモンスター１体を選択し、エンドフェイズ時までコントロールを得る』効果を発動する事はできますか？', '相手モンスターが自分フィールドのモンスターに対して攻撃を行ったバトルステップ中であれば、「{{エネミーコントローラー|5505}}」を発動し、攻撃の対象となっているモンスターをリリースする事はできます。\n（その場合、攻撃対象となったモンスターがフィールドに存在しなくなっていますので、戦闘の巻き戻しが発生します。）', '相手ノモンスターガ自分フィールドノモンスターニ対シテ攻撃ヲ行ッタ時ニソノ攻撃対象トナッタ自分フィールドノモンスターヲリリースシテエネミーコントローラー5505ノ●自分フィールド上ノモンスター1体ヲリリースシテ発動デキル相手フィールド上ニ表側表示デ存在スルモンスター1体ヲ選択シエンドフェイズ時マデコントロールヲ得ル効果ヲ発動スル事ハデキマスカ', '相手モンスターガ自分フィールドノモンスターニ対シテ攻撃ヲ行ッタバトルステップ中デアレバエネミーコントローラー5505ヲ発動シ攻撃ノ対象トナッテイルモンスターヲリリーススル事ハデキマスnソノ場合攻撃対象トナッタモンスターガフィールドニ存在シナクナッテイマスノデ戦闘ノ巻キ戻シガ発生シマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (148, '11561', '「{{ブンボーグ００３|11561}}」の『②：１ターンに１度、自分フィールドの「ブンボーグ」モンスター１体を対象として発動できる。そのモンスターの攻撃力・守備力はターン終了時まで、自分フィールドの「ブンボーグ」カードの数×５００アップする。この効果は相手ターンでも発動できる』効果が適用された後、自分フィールドに表側表示で存在する「ブンボーグ」と名のついたモンスターの数が変化した場合、攻撃力はどうなりますか？', '「{{ブンボーグ００３|11561}}」の効果適用後に、自分フィールドに表側表示で存在する「ブンボーグ」と名のついたモンスターの数が変化した場合でも、「{{ブンボーグ００３|11561}}」の効果によってアップしている数値は変化しません。', 'ブンボーグ00311561ノ②1ターンニ1度自分フィールドノブンボーグモンスター1体ヲ対象トシテ発動デキルソノモンスターノ攻撃力守備力ハターン終了時マデ自分フィールドノブンボーグカードノ数×500アップスルコノ効果ハ相手ターンデモ発動デキル効果ガ適用サレタ後自分フィールドニ表側表示デ存在スルブンボーグト名ノツイタモンスターノ数ガ変化シタ場合攻撃力ハドウナリマスカ', 'ブンボーグ00311561ノ効果適用後ニ自分フィールドニ表側表示デ存在スルブンボーグト名ノツイタモンスターノ数ガ変化シタ場合デモブンボーグ00311561ノ効果ニヨッテアップシテイル数値ハ変化シマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (147, '11087', '自分が「{{RUM－七皇の剣|11087}}」を発動し、その効果を一度適用しているデュエル中にて、2枚目となる「{{RUM－七皇の剣|11087}}」を通常のドローにてドローしました。\n\nこの場合、ドローした「{{RUM－七皇の剣|11087}}」を公開する事はできますか？', '既に「{{RUM－七皇の剣|11087}}」の効果を適用しているデュエル中には、「{{RUM－七皇の剣|11087}}」の発動は行えませんので、2枚目の「{{RUM－七皇の剣|11087}}」をドローしたとしても『自分のドローフェイズ時に通常のドローをしたこのカードを公開し続ける』事はできません。', '自分ガrum七皇ノ劍11087ヲ発動シソノ効果ヲ一度適用シテイルデュエル中ニテ2枚目トナルrum七皇ノ劍11087ヲ通常ノドローニテドローシマシタnnコノ場合ドローシタrum七皇ノ劍11087ヲ公開スル事ハデキマスカ', '既ニrum七皇ノ劍11087ノ効果ヲ適用シテイルデュエル中ニハrum七皇ノ劍11087ノ発動ハ行エマセンノデ2枚目ノrum七皇ノ劍11087ヲドローシタトシテモ自分ノドローフェイズ時ニ通常ノドローヲシタコノカードヲ公開シ続ケル事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (146, '10604', '「{{DZW－魔装鵺妖衣|10604}}」を装備しているモンスターが攻撃を行い、『装備モンスターの攻撃によって相手モンスターが破壊されなかったダメージステップ終了時、その相手モンスターの攻撃力を０にしてもう１度だけ同じモンスターに続けて攻撃できる』効果が発動しました。\n\n相手モンスターの攻撃力を０にする処理が行われた後、もう１度だけ同じモンスターに続けて攻撃を行う前に、「{{サイクロン|4909}}」等の何らかのカードの発動は行えますか？', '「{{DZW－魔装鵺妖衣|10604}}」の効果によって相手モンスターの攻撃力を0にした場合、『もう1度だけ同じモンスターに続けて攻撃できる』の効果によって行う攻撃宣言よりも前に、「{{サイクロン|4909}}」等の何らかのカードの発動を行う事はできます。', 'dzw魔装鵺妖衣10604ヲ装備シテイルモンスターガ攻撃ヲ行イ装備モンスターノ攻撃ニヨッテ相手モンスターガ破壊サレナカッタダメージステップ終了時ソノ相手モンスターノ攻撃力ヲ0ニシテモウ1度ダケ同ジモンスターニ続ケテ攻撃デキル効果ガ発動シマシタnn相手モンスターノ攻撃力ヲ0ニスル処理ガ行ワレタ後モウ1度ダケ同ジモンスターニ続ケテ攻撃ヲ行ウ前ニサイクロン4909等ノ何ラカノカードノ発動ハ行エマスカ', 'dzw魔装鵺妖衣10604ノ効果ニヨッテ相手モンスターノ攻撃力ヲ0ニシタ場合モウ1度ダケ同ジモンスターニ続ケテ攻撃デキルノ効果ニヨッテ行ウ攻撃宣言ヨリモ前ニサイクロン4909等ノ何ラカノカードノ発動ヲ行ウ事ハデキマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (145, '4851', '自分のバトルフェイズ中に相手「{{血の代償|4851}}」や「{{リビングデッドの呼び声|4989}}」等を発動した事で、モンスターの数が増減し、戦闘の巻き戻しが発生し、攻撃を取りやめました。\n\nメインフェイズ２にて、その攻撃を取りやめたモンスターの表示形式を変更する事はできますか？', '戦闘の巻き戻しが発生した結果、攻撃対象を選び直さずに攻撃を取りやめている場合でも、攻撃宣言は既に行っていますので、そのターンのメインフェイズ２にて、そのモンスターの表示形式を変更する事はできません。', '自分ノバトルフェイズ中ニ相手血ノ代償4851ヤリビングデッドノ呼ビ声4989等ヲ発動シタ事デモンスターノ数ガ増減シ戦闘ノ巻キ戻シガ発生シ攻撃ヲ取リヤメマシタnnメインフェイズ2ニテソノ攻撃ヲ取リヤメタモンスターノ表示形式ヲ変更スル事ハデキマスカ', '戦闘ノ巻キ戻シガ発生シタ結果攻撃対象ヲ選ビ直サズニ攻撃ヲ取リヤメテイル場合デモ攻撃宣言ハ既ニ行ッテイマスノデソノターンノメインフェイズ2ニテソノモンスターノ表示形式ヲ変更スル事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (144, '10650', '「{{星態龍|10650}}」が相手の「{{ギャラクシー･ドラグーン|10730}}」に攻撃した場合、それぞれの効果の適用はどうなりますか？', '「{{星態龍|10650}}」が「{{ギャラクシー･ドラグーン|10730}}」に攻撃した場合、まず、「{{星態龍|10650}}」の『このカードが攻撃する場合、このカードはダメージステップ終了時まで、このカード以外のカードの効果を受けない』効果がただちに適用されます。\n\n次に「{{ギャラクシー･ドラグーン|10730}}」の効果が適用されますが、『このカードはドラゴン族モンスターと戦闘を行う場合、バトルフェイズの間だけそのモンスターの効果は無効化され』の処理は「{{星態龍|10650}}」がカードの効果を受けないため、適用されません。\n\nその場合でも、『ダメージステップの間だけこのカードの攻撃力は1000ポイントアップする』処理は適用され、「{{ギャラクシー･ドラグーン|10730}}」の攻撃力は1000アップします。', '星態龍10650ガ相手ノギャラクシー･ドラグーン10730ニ攻撃シタ場合ソレゾレノ効果ノ適用ハドウナリマスカ', '星態龍10650ガギャラクシー･ドラグーン10730ニ攻撃シタ場合マズ星態龍10650ノコノカードガ攻撃スル場合コノカードハダメージステップ終了時マデコノカード以外ノカードノ効果ヲ受ケナイ効果ガタダチニ適用サレマスnn次ニギャラクシー･ドラグーン10730ノ効果ガ適用サレマスガコノカードハドラゴン族モンスタート戦闘ヲ行ウ場合バトルフェイズノ間ダケソノモンスターノ効果ハ無効化サレノ処理ハ星態龍10650ガカードノ効果ヲ受ケナイタメ適用サレマセンnnソノ場合デモダメージステップノ間ダケコノカードノ攻撃力ハ1000ポイントアップスル処理ハ適用サレギャラクシー･ドラグーン10730ノ攻撃力ハ1000アップシマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (143, '10604', '「{{DZW－魔装鵺妖衣|10604}}」が「{{サクリファイス|4737}}」の効果によって装備カード扱いとして装備されている場合、「{{DZW－魔装鵺妖衣|10604}}」の『このカードが装備カード扱いとして装備されている場合、装備モンスターは戦闘では破壊されない』効果や『装備モンスターの攻撃によって相手モンスターが破壊されなかったダメージステップ終了時、その相手モンスターの攻撃力を0にしてもう1度だけ同じモンスターに続けて攻撃できる』効果は適用されますか？', '「{{サクリファイス|4737}}」の効果によって装備魔法カード扱いとなっている場合でも、「{{DZW－魔装鵺妖衣|10604}}」のそれぞれの効果は適用されます。', 'dzw魔装鵺妖衣10604ガサクリファイス4737ノ効果ニヨッテ装備カード扱イトシテ装備サレテイル場合dzw魔装鵺妖衣10604ノコノカードガ装備カード扱イトシテ装備サレテイル場合装備モンスターハ戦闘デハ破壊サレナイ効果ヤ装備モンスターノ攻撃ニヨッテ相手モンスターガ破壊サレナカッタダメージステップ終了時ソノ相手モンスターノ攻撃力ヲ0ニシテモウ1度ダケ同ジモンスターニ続ケテ攻撃デキル効果ハ適用サレマスカ', 'サクリファイス4737ノ効果ニヨッテ装備魔法カード扱イトナッテイル場合デモdzw魔装鵺妖衣10604ノソレゾレノ効果ハ適用サレマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (142, '10724', '「{{傀儡儀式－パペット・リチューアル|10724}}」を発動する際に対象として選択した、自分の墓地の「ギミック・パペット」と名のついたレベル8モンスター2体の内1体が、相手がチェーンにて発動した「{{D.D.クロウ|6980}}」の効果によって除外され墓地に存在しなくなった場合、「{{傀儡儀式－パペット・リチューアル|10724}}」の処理はどうなりますか？', '「{{傀儡儀式－パペット・リチューアル|10724}}」の効果処理時に、対象のモンスター2体の内1体が墓地に存在しなくなっている場合でも、残りの1体のモンスターは特殊召喚されます。\n\n『このカードを発動するターン、自分はバトルフェイズを行えない』も通常通り適用されます。', '傀儡儀式パペットリチューアル10724ヲ発動スル際ニ対象トシテ選択シタ自分ノ墓地ノギミックパペットト名ノツイタレベル8モンスター2体ノ内1体ガ相手ガチェーンニテ発動シタd.d.クロウ6980ノ効果ニヨッテ除外サレ墓地ニ存在シナクナッタ場合傀儡儀式パペットリチューアル10724ノ処理ハドウナリマスカ', '傀儡儀式パペットリチューアル10724ノ効果処理時ニ対象ノモンスター2体ノ内1体ガ墓地ニ存在シナクナッテイル場合デモ残リノ1体ノモンスターハ特殊召喚サレマスnnコノカードヲ発動スルターン自分ハバトルフェイズヲ行エナイモ通常通リ適用サレマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (141, '12998', '相手が墓地で発動した、モンスターの効果の発動や、魔法・罠カードの効果の発動に対して、「{{コズミック・ブレイザー・ドラゴン|12998}}」の『●相手が魔法・罠・モンスターの効果を発動した時に発動できる。その発動を無効にし破壊する』モンスター効果を発動し、自身をエンドフェイズまで除外しています。\n\nその場合、墓地のモンスター・魔法・罠カードは破壊されませんが、除外された「{{コズミック・ブレイザー・ドラゴン|12998}}」はどうなりますか？', '自身のモンスター効果を発動する際に、コストとして除外された「{{コズミック・ブレイザー・ドラゴン|12998}}」は、墓地で発動したモンスター・魔法・罠カードの効果の発動を無効にし、『その発動を無効にし破壊する』処理によって、相手のモンスター・魔法・罠カードが破壊されなかった場合でも、そのターンのエンドフェイズに「{{コズミック・ブレイザー・ドラゴン|12998}}」をモンスターゾーンに戻す処理は通常通り適用されます。', '相手ガ墓地デ発動シタモンスターノ効果ノ発動ヤ魔法罠カードノ効果ノ発動ニ対シテコズミックブレイザードラゴン12998ノ●相手ガ魔法罠モンスターノ効果ヲ発動シタ時ニ発動デキルソノ発動ヲ無効ニシ破壊スルモンスター効果ヲ発動シ自身ヲエンドフェイズマデ除外シテイマスnnソノ場合墓地ノモンスター魔法罠カードハ破壊サレマセンガ除外サレタコズミックブレイザードラゴン12998ハドウナリマスカ', '自身ノモンスター効果ヲ発動スル際ニコストトシテ除外サレタコズミックブレイザードラゴン12998ハ墓地デ発動シタモンスター魔法罠カードノ効果ノ発動ヲ無効ニシソノ発動ヲ無効ニシ破壊スル処理ニヨッテ相手ノモンスター魔法罠カードガ破壊サレナカッタ場合デモソノターンノエンドフェイズニコズミックブレイザードラゴン12998ヲモンスターゾーンニ戻ス処理ハ通常通リ適用サレマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (140, '5124', '自分がモンスターで攻撃を宣言しました。その攻撃に対して、相手が「{{魔法の筒|5124}}」を発動した際に、さらにチェーンして相手が「{{リビングデッドの呼び声|4989}}」を発動した場合、その攻撃はどうなりますか？', '質問の状況の場合、チェーン２に発動した「{{リビングデッドの呼び声|4989}}」の効果によって相手フィールドにモンスターが特殊召喚されますが、その時点では戦闘の巻き戻しは発生せず、一連のチェーンの処理を先に行う事になります。\n\nこの場合、チェーン１に発動した「{{魔法の筒|5124}}」の効果によって、自分のモンスターの攻撃が無効になりますので、そのモンスターでそのまま攻撃を行う事はできず、戦闘の巻き戻しも結果的に発生しない事になります。', '自分ガモンスターデ攻撃ヲ宣言シマシタソノ攻撃ニ対シテ相手ガ魔法ノ筒5124ヲ発動シタ際ニサラニチェーンシテ相手ガリビングデッドノ呼ビ声4989ヲ発動シタ場合ソノ攻撃ハドウナリマスカ', '質問ノ状況ノ場合チェーン2ニ発動シタリビングデッドノ呼ビ声4989ノ効果ニヨッテ相手フィールドニモンスターガ特殊召喚サレマスガソノ時点デハ戦闘ノ巻キ戻シハ発生セズ一連ノチェーンノ処理ヲ先ニ行ウ事ニナリマスnnコノ場合チェーン1ニ発動シタ魔法ノ筒5124ノ効果ニヨッテ自分ノモンスターノ攻撃ガ無効ニナリマスノデソノモンスターデソノママ攻撃ヲ行ウ事ハデキズ戦闘ノ巻キ戻シモ結果的ニ発生シナイ事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (139, '4340', 'フィールド魔法「{{海|4340}}」が発動しており、相手フィールドに存在するモンスターが表側表示で存在する「{{伝説のフィッシャーマン|5069}}」のみの状況です。\n\nこの場合、自分のモンスターは「{{伝説のフィッシャーマン|5069}}」を攻撃対象にできず、プレイヤーを直接攻撃する事になりますが、その攻撃宣言時に「{{サイクロン|4909}}」で「{{海|4340}}」が破壊された場合、その攻撃はどうなりますか？', '質問の状況の場合、戦闘の巻き戻しが発生します。\n\n「{{伝説のフィッシャーマン|5069}}」を攻撃対象として選び直すか、攻撃を取りやめるかを選ぶ事になります。', 'フィールド魔法海4340ガ発動シテオリ相手フィールドニ存在スルモンスターガ表側表示デ存在スル伝説ノフィッシャーマン5069ノミノ状況デスnnコノ場合自分ノモンスターハ伝説ノフィッシャーマン5069ヲ攻撃対象ニデキズプレイヤーヲ直接攻撃スル事ニナリマスガソノ攻撃宣言時ニサイクロン4909デ海4340ガ破壊サレタ場合ソノ攻撃ハドウナリマスカ', '質問ノ状況ノ場合戦闘ノ巻キ戻シガ発生シマスnn伝説ノフィッシャーマン5069ヲ攻撃対象トシテ選ビ直スカ攻撃ヲ取リヤメルカヲ選ブ事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (138, '5350', '「{{非常食|5350}}」を発動する際に墓地へ送る魔法・罠カードとして、ペンデュラムゾーンに魔法カード扱いで存在するペンデュラムモンスターや魔法＆罠ゾーンに装備魔法カード扱いで存在するペンデュラムモンスターを選ぶ事はできますか？', 'ペンデュラムモンスターはフィールドから墓地へ送られる際には墓地へは行かず、エクストラデッキに加わります。\n「{{非常食|5350}}」を発動する際に、コストとして墓地へ送る魔法・罠カードとして、魔法カード扱いのペンデュラムモンスターを選ぶ事自体ができません。', '非常食5350ヲ発動スル際ニ墓地ヘ送ル魔法罠カードトシテペンデュラムゾーンニ魔法カード扱イデ存在スルペンデュラムモンスターヤ魔法罠ゾーンニ装備魔法カード扱イデ存在スルペンデュラムモンスターヲ選ブ事ハデキマスカ', 'ペンデュラムモンスターハフィールドカラ墓地ヘ送ラレル際ニハ墓地ヘハ行カズエクストラデッキニ加ワリマスn非常食5350ヲ発動スル際ニコストトシテ墓地ヘ送ル魔法罠カードトシテ魔法カード扱イノペンデュラムモンスターヲ選ブ事自体ガデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (137, '10020', '「{{フォトン・トライデント|10020}}」の効果が適用されているモンスターで攻撃を行う場合、『守備表示モンスターを攻撃した時、その守備力を攻撃力が超えていれば、その数値だけ相手ライフに戦闘ダメージを与える』効果によって相手に戦闘ダメージを与えた時のみ、『選択したモンスターが相手ライフに戦闘ダメージを与えた時、フィールド上の魔法・罠カード１枚を選択して破壊できる』効果を発動する事ができますか？\n\n「{{フォトン・トライデント|10020}}」の効果が適用されているモンスターが相手の攻撃表示モンスターと戦闘を行い、戦闘ダメージを与えた場合や、相手プレイヤーに直接攻撃し、戦闘ダメージを与えた場合にも『選択したモンスターが相手ライフに戦闘ダメージを与えた時、フィールド上の魔法・罠カード１枚を選択して破壊できる』効果を発動する事はできますか？', '「{{フォトン・トライデント|10020}}」の効果が適用されているモンスターが、そのターンに相手ライフに戦闘ダメージを与えたのであれば、『守備表示モンスターを攻撃した時、その守備力を攻撃力が超えていれば、その数値だけ相手ライフに戦闘ダメージを与える』効果によって戦闘ダメージを与えた時だけでなく、攻撃表示モンスターと戦闘を行って相手に戦闘ダメージを与えた時や、直接攻撃を行って相手に戦闘ダメージを与えた時にも、『フィールド上の魔法・罠カード1枚を選択して破壊できる』効果を発動する事ができます。', 'フォトントライデント10020ノ効果ガ適用サレテイルモンスターデ攻撃ヲ行ウ場合守備表示モンスターヲ攻撃シタ時ソノ守備力ヲ攻撃力ガ超エテイレバソノ数値ダケ相手ライフニ戦闘ダメージヲ与エル効果ニヨッテ相手ニ戦闘ダメージヲ与エタ時ノミ選択シタモンスターガ相手ライフニ戦闘ダメージヲ与エタ時フィールド上ノ魔法罠カード1枚ヲ選択シテ破壊デキル効果ヲ発動スル事ガデキマスカnnフォトントライデント10020ノ効果ガ適用サレテイルモンスターガ相手ノ攻撃表示モンスタート戦闘ヲ行イ戦闘ダメージヲ与エタ場合ヤ相手プレイヤーニ直接攻撃シ戦闘ダメージヲ与エタ場合ニモ選択シタモンスターガ相手ライフニ戦闘ダメージヲ与エタ時フィールド上ノ魔法罠カード1枚ヲ選択シテ破壊デキル効果ヲ発動スル事ハデキマスカ', 'フォトントライデント10020ノ効果ガ適用サレテイルモンスターガソノターンニ相手ライフニ戦闘ダメージヲ与エタノデアレバ守備表示モンスターヲ攻撃シタ時ソノ守備力ヲ攻撃力ガ超エテイレバソノ数値ダケ相手ライフニ戦闘ダメージヲ与エル効果ニヨッテ戦闘ダメージヲ与エタ時ダケデナク攻撃表示モンスタート戦闘ヲ行ッテ相手ニ戦闘ダメージヲ与エタ時ヤ直接攻撃ヲ行ッテ相手ニ戦闘ダメージヲ与エタ時ニモフィールド上ノ魔法罠カード1枚ヲ選択シテ破壊デキル効果ヲ発動スル事ガデキマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (135, '6682', '「{{マクロコスモス|6682}}」の効果適用中に「{{狂戦士の魂|11153}}」を発動する事はできますか？', '「{{マクロコスモス|6682}}」の効果適用中に「{{狂戦士の魂|11153}}」を発動する事はできます。（「{{狂戦士の魂|11153}}」を発動する際に捨てた手札は全て除外されます。）\n\n「{{狂戦士の魂|11153}}」の効果処理にてデッキの一番上のカードをめくり、それがモンスターカードだった場合でも、そのカードは墓地に送られず除外され、相手にダメージを与える事はできません。\n『その後、モンスターカード以外がめくられるまでこの効果を繰り返す』事もできません。', 'マクロコスモス6682ノ効果適用中ニ狂戦士ノ魂11153ヲ発動スル事ハデキマスカ', 'マクロコスモス6682ノ効果適用中ニ狂戦士ノ魂11153ヲ発動スル事ハデキマス狂戦士ノ魂11153ヲ発動スル際ニ捨テタ手札ハ全テ除外サレマスnn狂戦士ノ魂11153ノ効果処理ニテデッキノ一番上ノカードヲメクリソレガモンスターカードダッタ場合デモソノカードハ墓地ニ送ラレズ除外サレ相手ニダメージヲ与エル事ハデキマセンnソノ後モンスターカード以外ガメクラレルマデコノ効果ヲ繰リ返ス事モデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (132, '6682', '「{{マクロコスモス|6682}}」の『このカードがフィールド上に存在する限り、墓地へ送られるカードは墓地へは行かずゲームから除外される』効果が適用されている場合、相手モンスターの攻撃宣言時に「{{検問|12479}}」を発動する事はできますか？', '「{{マクロコスモス|6682}}」の効果が適用されている場合でも、「{{検問|12479}}」を発動する事はできます。\n\n『相手の手札を全て確認し、その中にモンスターカードがあった場合、その攻撃を無効にする』処理は通常通り適用される事になります。\n\nなお、攻撃を無効にする処理が行われ、『その後、自分は相手の手札からモンスター１体を選んで捨てる』処理が適用される場合には、その際に捨てる手札は墓地へは送られず、除外される事になります。', 'マクロコスモス6682ノコノカードガフィールド上ニ存在スル限リ墓地ヘ送ラレルカードハ墓地ヘハ行カズゲームカラ除外サレル効果ガ適用サレテイル場合相手モンスターノ攻撃宣言時ニ検問12479ヲ発動スル事ハデキマスカ', 'マクロコスモス6682ノ効果ガ適用サレテイル場合デモ検問12479ヲ発動スル事ハデキマスnn相手ノ手札ヲ全テ確認シソノ中ニモンスターカードガアッタ場合ソノ攻撃ヲ無効ニスル処理ハ通常通リ適用サレル事ニナリマスnnナオ攻撃ヲ無効ニスル処理ガ行ワレソノ後自分ハ相手ノ手札カラモンスター1体ヲ選ンデ捨テル処理ガ適用サレル場合ニハソノ際ニ捨テル手札ハ墓地ヘハ送ラレズ除外サレル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (130, '5448', '「{{無謀な欲張り|5448}}」を同一ターンに2枚発動した場合、『その後、自分のドローフェイズを２回スキップする』処理はどのように適用されますか？', '「{{無謀な欲張り|5448}}」を発動した場合、次の自分のターンのドローフェイズと、その次の自分のターンのドローフェイズの２回がスキップされる事になります。\n\n同一のターンに「{{無謀な欲張り|5448}}」を２枚発動した場合、それぞれの「{{無謀な欲張り|5448}}」の効果が適用され、次の自分のターンのドローフェイズと、その次の自分のターンのドローフェイズの２回がスキップされる事になります。\n\n結果的に、スキップされるドローフェイズは2回となります。', '無謀ナ欲張リ5448ヲ同一ターンニ2枚発動シタ場合ソノ後自分ノドローフェイズヲ2回スキップスル処理ハドノヨウニ適用サレマスカ', '無謀ナ欲張リ5448ヲ発動シタ場合次ノ自分ノターンノドローフェイズトソノ次ノ自分ノターンノドローフェイズノ2回ガスキップサレル事ニナリマスnn同一ノターンニ無謀ナ欲張リ5448ヲ2枚発動シタ場合ソレゾレノ無謀ナ欲張リ5448ノ効果ガ適用サレ次ノ自分ノターンノドローフェイズトソノ次ノ自分ノターンノドローフェイズノ2回ガスキップサレル事ニナリマスnn結果的ニスキップサレルドローフェイズハ2回トナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (129, '11904', '「{{コミックハンド|11904}}」の『①：装備モンスターのコントロールを得る』効果によってコントロールを得た、元々の持ち主が相手のモンスターで攻撃を行った際、そのダメージ計算時に「{{禁じられた聖典|11096}}」が発動し、『ダメージステップ終了時まで、このカード以外のフィールド上のカードの効果は無効化され、その戦闘のダメージ計算は元々の攻撃力・守備力で行う』効果が適用された場合、攻撃はどうなりますか？', '質問の状況の場合、「{{禁じられた聖典|11096}}」の効果で「{{コミックハンド|11904}}」の効果が無効になった事によって、攻撃宣言を行ったモンスターのコントロールが相手に戻ります。\n\nしたがって、その場合には戦闘ダメージ計算は行われず、ダメージステップが終了する事になります。', 'コミックハンド11904ノ①装備モンスターノコントロールヲ得ル効果ニヨッテコントロールヲ得タ元々ノ持チ主ガ相手ノモンスターデ攻撃ヲ行ッタ際ソノダメージ計算時ニ禁ジラレタ聖典11096ガ発動シダメージステップ終了時マデコノカード以外ノフィールド上ノカードノ効果ハ無効化サレソノ戦闘ノダメージ計算ハ元々ノ攻撃力守備力デ行ウ効果ガ適用サレタ場合攻撃ハドウナリマスカ', '質問ノ状況ノ場合禁ジラレタ聖典11096ノ効果デコミックハンド11904ノ効果ガ無効ニナッタ事ニヨッテ攻撃宣言ヲ行ッタモンスターノコントロールガ相手ニ戻リマスnnシタガッテソノ場合ニハ戦闘ダメージ計算ハ行ワレズダメージステップガ終了スル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (128, '11990', '裏側守備表示の「{{レッド・デーモンズ・ドラゴン・スカーライト|11990}}」をリリースして、「{{バスター・モード|8058}}」を発動する事はできますか？', '裏側守備表示の「{{レッド・デーモンズ・ドラゴン・スカーライト|11990}}」は、『①：このカードのカード名は、フィールド・墓地に存在する限り「{{レッド・デーモンズ・ドラゴン|7735}}」として扱う』効果が適用されていない状態ですので、「{{レッド・デーモンズ・ドラゴン|7735}}」としては扱われていません。\n\nしたがって、「{{バスター・モード|8058}}」を発動する際に、裏側守備表示の「{{レッド・デーモンズ・ドラゴン・スカーライト|11990}}」をリリースする事はできません。', '裏側守備表示ノレッドデーモンズドラゴンスカーライト11990ヲリリースシテバスターモード8058ヲ発動スル事ハデキマスカ', '裏側守備表示ノレッドデーモンズドラゴンスカーライト11990ハ①コノカードノカード名ハフィールド墓地ニ存在スル限リレッドデーモンズドラゴン7735トシテ扱ウ効果ガ適用サレテイナイ状態デスノデレッドデーモンズドラゴン7735トシテハ扱ワレテイマセンnnシタガッテバスターモード8058ヲ発動スル際ニ裏側守備表示ノレッドデーモンズドラゴンスカーライト11990ヲリリーススル事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (127, '13001', '「{{集いし願い|13001}}」の効果によって特殊召喚されている「{{スターダスト・ドラゴン|7734}}」が、自身の『①：フィールドのカードを破壊する魔法・罠・モンスターの効果が発動した時、このカードをリリースして発動できる。その発動を無効にし破壊する』モンスター効果を発動し、リリースされ墓地へ送られた場合、エンドフェイズの処理はどうなりますか？', '「{{集いし願い|13001}}」の効果によって特殊召喚されている「{{スターダスト・ドラゴン|7734}}」が自身のモンスター効果を発動しリリースされた場合、そのターンのエンドフェイズに、「{{集いし願い|13001}}」の『この効果で特殊召喚したモンスターはエンドフェイズに除外される』処理によって除外される事はありません。\n\nまた、「{{集いし願い|13001}}」の効果によって特殊召喚されている「{{スターダスト・ドラゴン|7734}}」は正規の手順によって特殊召喚された扱いとなりますので、「{{スターダスト・ドラゴン|7734}}」は『②：このカードの①の効果を適用したターンのエンドフェイズに発動できる。その効果を発動するためにリリースしたこのカードを墓地から特殊召喚する』モンスター効果を発動し、墓地から特殊召喚する事ができます。', '集イシ願イ13001ノ効果ニヨッテ特殊召喚サレテイルスターダストドラゴン7734ガ自身ノ①フィールドノカードヲ破壊スル魔法罠モンスターノ効果ガ発動シタ時コノカードヲリリースシテ発動デキルソノ発動ヲ無効ニシ破壊スルモンスター効果ヲ発動シリリースサレ墓地ヘ送ラレタ場合エンドフェイズノ処理ハドウナリマスカ', '集イシ願イ13001ノ効果ニヨッテ特殊召喚サレテイルスターダストドラゴン7734ガ自身ノモンスター効果ヲ発動シリリースサレタ場合ソノターンノエンドフェイズニ集イシ願イ13001ノコノ効果デ特殊召喚シタモンスターハエンドフェイズニ除外サレル処理ニヨッテ除外サレル事ハアリマセンnnマタ集イシ願イ13001ノ効果ニヨッテ特殊召喚サレテイルスターダストドラゴン7734ハ正規ノ手順ニヨッテ特殊召喚サレタ扱イトナリマスノデスターダストドラゴン7734ハ②コノカードノ①ノ効果ヲ適用シタターンノエンドフェイズニ発動デキルソノ効果ヲ発動スルタメニリリースシタコノカードヲ墓地カラ特殊召喚スルモンスター効果ヲ発動シ墓地カラ特殊召喚スル事ガデキマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (126, '11541', '「{{クリフォート・アクセス|11541}}」をリリースなしで召喚し、『②：特殊召喚またはリリースなしで召喚したこのカードのレベルは４になり、元々の攻撃力は１８００になる』モンスター効果が適用されています。\n\nこの状況で、「{{Emミラー・コンダクター|11959}}」の『①：１ターンに１度、フィールドの表側表示モンスター１体を対象として発動できる。そのモンスターの攻撃力・守備力をターン終了時まで入れ替える。その後、自分は５００ダメージを受ける。この効果は相手ターンでも発動できる』モンスター効果が適用され、「{{クリフォート・アクセス|11541}}」の攻撃力・守備力が入れ替わりました。\n\nその後、「{{スキルドレイン|5740}}」が発動し、「{{クリフォート・アクセス|11541}}」の効果が無効になった場合、攻撃力・守備力はどうなりますか？', '質問の状況の場合、まず、「{{Emミラー・コンダクター|11959}}」のモンスター効果によって、リリースなしで召喚されている「{{クリフォート・アクセス|11541}}」の攻撃力・守備力が入れ替わり、ATK1000・DEF1800の状態になります。\n\nその状況で「{{スキルドレイン|5740}}」が適用された場合、「{{クリフォート・アクセス|11541}}」の『②：特殊召喚またはリリースなしで召喚したこのカードのレベルは４になり、元々の攻撃力は１８００になる』効果は無効になりますが、「{{Emミラー・コンダクター|11959}}」のモンスター効果が適用されていますので、その時点では、ATK1000・DEF1800の状態のままです。\n\nその後、ターン終了時に、「{{Emミラー・コンダクター|11959}}」のモンスター効果の適用がなくなった際には、「{{クリフォート・アクセス|11541}}」はATK2800・DEF1000の状態になります。', 'クリフォートアクセス11541ヲリリースナシデ召喚シ②特殊召喚マタハリリースナシデ召喚シタコノカードノレベルハ4ニナリ元々ノ攻撃力ハ1800ニナルモンスター効果ガ適用サレテイマスnnコノ状況デemミラーコンダクター11959ノ①1ターンニ1度フィールドノ表側表示モンスター1体ヲ対象トシテ発動デキルソノモンスターノ攻撃力守備力ヲターン終了時マデ入レ替エルソノ後自分ハ500ダメージヲ受ケルコノ効果ハ相手ターンデモ発動デキルモンスター効果ガ適用サレクリフォートアクセス11541ノ攻撃力守備力ガ入レ替ワリマシタnnソノ後スキルドレイン5740ガ発動シクリフォートアクセス11541ノ効果ガ無効ニナッタ場合攻撃力守備力ハドウナリマスカ', '質問ノ状況ノ場合マズemミラーコンダクター11959ノモンスター効果ニヨッテリリースナシデ召喚サレテイルクリフォートアクセス11541ノ攻撃力守備力ガ入レ替ワリatk1000def1800ノ状態ニナリマスnnソノ状況デスキルドレイン5740ガ適用サレタ場合クリフォートアクセス11541ノ②特殊召喚マタハリリースナシデ召喚シタコノカードノレベルハ4ニナリ元々ノ攻撃力ハ1800ニナル効果ハ無効ニナリマスガemミラーコンダクター11959ノモンスター効果ガ適用サレテイマスノデソノ時点デハatk1000def1800ノ状態ノママデスnnソノ後ターン終了時ニemミラーコンダクター11959ノモンスター効果ノ適用ガナクナッタ際ニハクリフォートアクセス11541ハatk2800def1000ノ状態ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (125, '4989', '自分のモンスターゾーンに存在する全てのモンスターでの攻撃が終了し、バトルステップになりました。\n\nこの場合、バトルステップにカードの効果を発動できますか？\nそれとも、ただちにエンドステップに移ってしまい、カードの発動をバトルステップ中には行えませんか？', 'バトルフェイズ中に、自分のモンスターゾーンに存在するモンスターの全ての攻撃が終了し、バトルステップに戻ったとしても、ただちにエンドステップに移るわけではありません。\n\n攻撃が終了した後のバトルステップの間に、カードの効果の発動を行う事はできます。\n（例えば、「{{リビングデッドの呼び声|4989}}」を発動し、新たなモンスターを特殊召喚したのであれば、そのモンスターで攻撃を行う事もできます。）', '自分ノモンスターゾーンニ存在スル全テノモンスターデノ攻撃ガ終了シバトルステップニナリマシタnnコノ場合バトルステップニカードノ効果ヲ発動デキマスカnソレトモタダチニエンドステップニ移ッテシマイカードノ発動ヲバトルステップ中ニハ行エマセンカ', 'バトルフェイズ中ニ自分ノモンスターゾーンニ存在スルモンスターノ全テノ攻撃ガ終了シバトルステップニ戻ッタトシテモタダチニエンドステップニ移ルワケデハアリマセンnn攻撃ガ終了シタ後ノバトルステップノ間ニカードノ効果ノ発動ヲ行ウ事ハデキマスn例エバリビングデッドノ呼ビ声4989ヲ発動シ新タナモンスターヲ特殊召喚シタノデアレバソノモンスターデ攻撃ヲ行ウ事モデキマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (124, '12499', '自分のモンスターゾーンに表側攻撃表示の「{{キウイ・マジシャン・ガール|12499}}」1体のみが存在し、自分の魔法＆罠ゾーンには表側表示の「{{マジシャンズ・プロテクション|12511}}」が存在しています。\n\nこの状況で相手の「{{青眼の亜白龍|12253}}」が「{{キウイ・マジシャン・ガール|12499}}」を攻撃し、戦闘で破壊される場合、「{{マジシャンズ・プロテクション|12511}}」の『①：自分フィールドに魔法使い族モンスターが存在する限り、自分が受ける全てのダメージは半分になる』効果は適用されますか？', '質問の状況の場合、自分のモンスターゾーンに魔法使い族モンスターが存在していますので、その戦闘ダメージ計算の際にも、「{{マジシャンズ・プロテクション|12511}}」の『①：自分フィールドに魔法使い族モンスターが存在する限り、自分が受ける全てのダメージは半分になる』効果は適用される事になります。\n\nこの場合、「{{青眼の亜白龍|12253}}」の攻撃力3000と、「{{キウイ・マジシャン・ガール|12499}}」の攻撃力1800の差分となる1200の半分、600の戦闘ダメージを自分が受け、「{{キウイ・マジシャン・ガール|12499}}」は戦闘で破壊され墓地へ送られる事になります。\n（これによって、自分のモンスターゾーンに魔法使い族モンスターが存在しなくなっていますので、「{{マジシャンズ・プロテクション|12511}}」の効果によってダメージが半分にならない状態に戻ります。）', '自分ノモンスターゾーンニ表側攻撃表示ノキウイマジシャンガール124991体ノミガ存在シ自分ノ魔法罠ゾーンニハ表側表示ノマジシャンズプロテクション12511ガ存在シテイマスnnコノ状況デ相手ノ青眼ノ亜白龍12253ガキウイマジシャンガール12499ヲ攻撃シ戦闘デ破壊サレル場合マジシャンズプロテクション12511ノ①自分フィールドニ魔法使イ族モンスターガ存在スル限リ自分ガ受ケル全テノダメージハ半分ニナル効果ハ適用サレマスカ', '質問ノ状況ノ場合自分ノモンスターゾーンニ魔法使イ族モンスターガ存在シテイマスノデソノ戦闘ダメージ計算ノ際ニモマジシャンズプロテクション12511ノ①自分フィールドニ魔法使イ族モンスターガ存在スル限リ自分ガ受ケル全テノダメージハ半分ニナル効果ハ適用サレル事ニナリマスnnコノ場合青眼ノ亜白龍12253ノ攻撃力3000トキウイマジシャンガール12499ノ攻撃力1800ノ差分トナル1200ノ半分600ノ戦闘ダメージヲ自分ガ受ケキウイマジシャンガール12499ハ戦闘デ破壊サレ墓地ヘ送ラレル事ニナリマスnコレニヨッテ自分ノモンスターゾーンニ魔法使イ族モンスターガ存在シナクナッテイマスノデマジシャンズプロテクション12511ノ効果ニヨッテダメージガ半分ニナラナイ状態ニ戻リマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (123, '11584', '「{{青天の霹靂|11584}}」の効果で特殊召喚した「{{毒蛇神ヴェノミナーガ|7184}}」は、「{{青天の霹靂|11584}}」の『この効果で特殊召喚したモンスターは、そのモンスター以外の自分のカードの効果を受けず、次の相手エンドフェイズに持ち主のデッキに戻る』処理によって、デッキに戻りますか？', '「{{毒蛇神ヴェノミナーガ|7184}}」は、「{{青天の霹靂|11584}}」の効果で特殊召喚される場合、『この効果で特殊召喚したモンスターは、そのモンスター以外の自分のカードの効果を受けず、次の相手エンドフェイズに持ち主のデッキに戻る』効果が適用され特殊召喚される事になりますので、自身の『このカードはフィールド上に表側表示で存在する限り、このカード以外のカードの効果の対象にならず、効果も受けない』効果の影響を受ける事なく、通常通り、次の相手のエンドフェイズに持ち主のデッキに戻る事になります。', '青天ノ霹靂11584ノ効果デ特殊召喚シタ毒蛇神ヴェノミナーガ7184ハ青天ノ霹靂11584ノコノ効果デ特殊召喚シタモンスターハソノモンスター以外ノ自分ノカードノ効果ヲ受ケズ次ノ相手エンドフェイズニ持チ主ノデッキニ戻ル処理ニヨッテデッキニ戻リマスカ', '毒蛇神ヴェノミナーガ7184ハ青天ノ霹靂11584ノ効果デ特殊召喚サレル場合コノ効果デ特殊召喚シタモンスターハソノモンスター以外ノ自分ノカードノ効果ヲ受ケズ次ノ相手エンドフェイズニ持チ主ノデッキニ戻ル効果ガ適用サレ特殊召喚サレル事ニナリマスノデ自身ノコノカードハフィールド上ニ表側表示デ存在スル限リコノカード以外ノカードノ効果ノ対象ニナラズ効果モ受ケナイ効果ノ影響ヲ受ケル事ナク通常通リ次ノ相手ノエンドフェイズニ持チ主ノデッキニ戻ル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (122, '6639', '除外されているカードが全て融合・シンクロ・エクシーズ・リンクモンスターだった場合、発動した「{{E・HERO エリクシーラー|6639}}」の『このカードが融合召喚に成功した時、ゲームから除外された全てのカードを持ち主のデッキに戻し、デッキをシャッフルする』モンスター効果の処理はどうなりますか？', '除外されているカードが全て融合・シンクロ・エクシーズ・リンクモンスターだった場合でも、融合召喚に成功した「{{E・HERO エリクシーラー|6639}}」のモンスター効果は発動し、効果処理は通常通り適用されます。\n\nその場合、除外されている融合・シンクロ・エクシーズ・リンクモンスターは全て持ち主のエクストラデッキに戻します。\nなお、この場合、デッキにカードは1枚も戻っていませんので、デッキのシャッフルは行いません。', '除外サレテイルカードガ全テ融合シンクロエクシーズリンクモンスターダッタ場合発動シタeheroエリクシーラー6639ノコノカードガ融合召喚ニ成功シタ時ゲームカラ除外サレタ全テノカードヲ持チ主ノデッキニ戻シデッキヲシャッフルスルモンスター効果ノ処理ハドウナリマスカ', '除外サレテイルカードガ全テ融合シンクロエクシーズリンクモンスターダッタ場合デモ融合召喚ニ成功シタeheroエリクシーラー6639ノモンスター効果ハ発動シ効果処理ハ通常通リ適用サレマスnnソノ場合除外サレテイル融合シンクロエクシーズリンクモンスターハ全テ持チ主ノエクストラデッキニ戻シマスnナオコノ場合デッキニカードハ1枚モ戻ッテイマセンノデデッキノシャッフルハ行イマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (121, '8870', '「ダークソウルトークン」と「{{冥界龍 ドラゴネクロ|8870}}」が戦闘を行った場合、『このカードがモンスターと戦闘を行ったダメージステップ終了時、そのモンスターの攻撃力は０になり、そのモンスターの元々のレベル・攻撃力を持つ「ダークソウルトークン」（アンデット族・闇・星？・攻？／守０）１体を自分フィールド上に特殊召喚する』効果は発動しますか？', '「ダークソウルトークン」と「{{冥界龍 ドラゴネクロ|8870}}」が戦闘した場合でも、「{{冥界龍 ドラゴネクロ|8870}}」の効果は発動します。\n\n「ダークソウルトークン」は元々のレベルを持たないモンスターですので、「{{冥界龍 ドラゴネクロ|8870}}」の効果が発動した際に、『このカードがモンスターと戦闘を行ったダメージステップ終了時、そのモンスターの攻撃力は０になり』の処理は適用されますが、「ダークソウルトークン」を特殊召喚する処理は適用されません。', 'ダークソウルトークント冥界龍ドラゴネクロ8870ガ戦闘ヲ行ッタ場合コノカードガモンスタート戦闘ヲ行ッタダメージステップ終了時ソノモンスターノ攻撃力ハ0ニナリソノモンスターノ元々ノレベル攻撃力ヲ持ツダークソウルトークンアンデット族闇星攻守01体ヲ自分フィールド上ニ特殊召喚スル効果ハ発動シマスカ', 'ダークソウルトークント冥界龍ドラゴネクロ8870ガ戦闘シタ場合デモ冥界龍ドラゴネクロ8870ノ効果ハ発動シマスnnダークソウルトークンハ元々ノレベルヲ持タナイモンスターデスノデ冥界龍ドラゴネクロ8870ノ効果ガ発動シタ際ニコノカードガモンスタート戦闘ヲ行ッタダメージステップ終了時ソノモンスターノ攻撃力ハ0ニナリノ処理ハ適用サレマスガダークソウルトークンヲ特殊召喚スル処理ハ適用サレマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (120, '6668', 'お互いのプレイヤーのフィールドゾーンに、「{{幽獄の時計塔|6668}}」が表側表示で存在しています。\n\nこの状況で「{{エターナル・ドレッド|6953}}」が発動し、処理を行う場合、どちらの「{{幽獄の時計塔|6668}}」に時計カウンターが置かれる事になりますか？', 'お互いのフィールドゾーンに「{{幽獄の時計塔|6668}}」が表側表示で存在する状況にて、「{{エターナル・ドレッド|6953}}」が発動した場合、お互いの「{{幽獄の時計塔|6668}}」に時計カウンターが2つずつ置かれる事になります。\n（どちらかの「{{幽獄の時計塔|6668}}」にだけ時計カウンターを置く、とする事はできません。必ずお互いの「{{幽獄の時計塔|6668}}」に時計カウンターを置きます。）', 'オ互イノプレイヤーノフィールドゾーンニ幽獄ノ時計塔6668ガ表側表示デ存在シテイマスnnコノ状況デエターナルドレッド6953ガ発動シ処理ヲ行ウ場合ドチラノ幽獄ノ時計塔6668ニ時計カウンターガ置カレル事ニナリマスカ', 'オ互イノフィールドゾーンニ幽獄ノ時計塔6668ガ表側表示デ存在スル状況ニテエターナルドレッド6953ガ発動シタ場合オ互イノ幽獄ノ時計塔6668ニ時計カウンターガ2ツズツ置カレル事ニナリマスnドチラカノ幽獄ノ時計塔6668ニダケ時計カウンターヲ置クトスル事ハデキマセン必ズオ互イノ幽獄ノ時計塔6668ニ時計カウンターヲ置キマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (118, '11607', 'バトルフェイズにて戦闘を行い、相手に戦闘ダメージを与えている自分ターンのメインフェイズ2にて、「{{転回操車|11607}}」の『①：自分フィールドに機械族・地属性・レベル１０モンスターが召喚・特殊召喚された場合に発動できる。デッキから攻撃力１８００以上の機械族・地属性・レベル４モンスター１体を特殊召喚する。この効果で特殊召喚されたモンスターのレベルは１０になる。この効果の発動後、ターン終了時まで相手が受ける戦闘ダメージは０になる』効果を発動する事はできますか？', '質問の状況の場合でも、メインフェイズ２にて「{{転回操車|11607}}」の効果を発動する事ができます。\n\nなお、『この効果の発動後、ターン終了時まで相手が受ける戦闘ダメージは０になる』処理は、そのターンに「{{転回操車|11607}}」の効果が適用された以降、相手に戦闘ダメージが与えられる際に適用される処理となります。このターンに既に相手に与えている戦闘ダメージが０になる事はありません。', 'バトルフェイズニテ戦闘ヲ行イ相手ニ戦闘ダメージヲ与エテイル自分ターンノメインフェイズ2ニテ転回操車11607ノ①自分フィールドニ機械族地属性レベル10モンスターガ召喚特殊召喚サレタ場合ニ発動デキルデッキカラ攻撃力1800以上ノ機械族地属性レベル4モンスター1体ヲ特殊召喚スルコノ効果デ特殊召喚サレタモンスターノレベルハ10ニナルコノ効果ノ発動後ターン終了時マデ相手ガ受ケル戦闘ダメージハ0ニナル効果ヲ発動スル事ハデキマスカ', '質問ノ状況ノ場合デモメインフェイズ2ニテ転回操車11607ノ効果ヲ発動スル事ガデキマスnnナオコノ効果ノ発動後ターン終了時マデ相手ガ受ケル戦闘ダメージハ0ニナル処理ハソノターンニ転回操車11607ノ効果ガ適用サレタ以降相手ニ戦闘ダメージガ与エラレル際ニ適用サレル処理トナリマスコノターンニ既ニ相手ニ与エテイル戦闘ダメージガ0ニナル事ハアリマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (117, '8085', '自分のモンスターゾーンに魔力カウンターが1つ置かれた「{{マジックテンペスター|8085}}」が存在し、自分のフィールドゾーンに魔力カウンターが4つ置かれた「{{魔法都市エンディミオン|8135}}」が存在しています。\n\nこの状況で、「{{マジックテンペスター|8085}}」の『フィールド上に存在する魔力カウンターを全て取り除く事で、その個数×５００ポイントダメージを相手ライフに与える』効果を発動する際に、「{{魔法都市エンディミオン|8135}}」の『１ターンに１度、自分フィールド上に存在する魔力カウンターを取り除いて自分のカードの効果を発動する場合、代わりにこのカードに乗っている魔力カウンターを取り除く事ができる』効果を適用する事はできますか？', '「{{マジックテンペスター|8085}}」の効果を発動する際には、フィールドに存在する全ての魔力カウンターを取り除かなければなりません。\n\n質問の状況の場合、「{{魔法都市エンディミオン|8135}}」の効果を適用する事はできず、「{{マジックテンペスター|8085}}」に置かれている魔力カウンターと、「{{魔法都市エンディミオン|8135}}」に置かれている魔力カウンターの全てを取り除いて、「{{マジックテンペスター|8085}}」の効果を発動する事になります。', '自分ノモンスターゾーンニ魔力カウンターガ1ツ置カレタマジックテンペスター8085ガ存在シ自分ノフィールドゾーンニ魔力カウンターガ4ツ置カレタ魔法都市エンディミオン8135ガ存在シテイマスnnコノ状況デマジックテンペスター8085ノフィールド上ニ存在スル魔力カウンターヲ全テ取リ除ク事デソノ個数×500ポイントダメージヲ相手ライフニ与エル効果ヲ発動スル際ニ魔法都市エンディミオン8135ノ1ターンニ1度自分フィールド上ニ存在スル魔力カウンターヲ取リ除イテ自分ノカードノ効果ヲ発動スル場合代ワリニコノカードニ乗ッテイル魔力カウンターヲ取リ除ク事ガデキル効果ヲ適用スル事ハデキマスカ', 'マジックテンペスター8085ノ効果ヲ発動スル際ニハフィールドニ存在スル全テノ魔力カウンターヲ取リ除カナケレバナリマセンnn質問ノ状況ノ場合魔法都市エンディミオン8135ノ効果ヲ適用スル事ハデキズマジックテンペスター8085ニ置カレテイル魔力カウンタート魔法都市エンディミオン8135ニ置カレテイル魔力カウンターノ全テヲ取リ除イテマジックテンペスター8085ノ効果ヲ発動スル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (115, '5533', '「{{王家の眠る谷－ネクロバレー|5533}}」の効果適用中に、「{{トリシューラの影霊衣|11485}}」の『②：このカードが儀式召喚に成功した時に発動できる。相手の手札・フィールド・墓地のカードをそれぞれ１枚選び、その３枚を除外する』効果を発動する事はできますか？', '「{{王家の眠る谷－ネクロバレー|5533}}」の効果が適用されている場合、墓地のカードを除外する事ができません。\n\nしたがって、儀式召喚された「{{トリシューラの影霊衣|11485}}」の効果を発動する事はできません。', '王家ノ眠ル谷ネクロバレー5533ノ効果適用中ニトリシューラノ影霊衣11485ノ②コノカードガ儀式召喚ニ成功シタ時ニ発動デキル相手ノ手札フィールド墓地ノカードヲソレゾレ1枚選ビソノ3枚ヲ除外スル効果ヲ発動スル事ハデキマスカ', '王家ノ眠ル谷ネクロバレー5533ノ効果ガ適用サレテイル場合墓地ノカードヲ除外スル事ガデキマセンnnシタガッテ儀式召喚サレタトリシューラノ影霊衣11485ノ効果ヲ発動スル事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (114, '5482', '「{{死霊操りしパペットマスター|5482}}」の『①：このカードがアドバンス召喚に成功した時、２０００LPを払い、自分の墓地の悪魔族モンスター２体を対象として発動できる。その悪魔族モンスターを特殊召喚する。この効果で特殊召喚したモンスターはこのターン攻撃できない』効果の発動にチェーンして、相手が「{{D.D.クロウ|6980}}」を発動し、対象となる２体の悪魔族モンスターのうち、１体が墓地に存在しなくなりました。\n\nこの場合、効果処理はどうなりますか？', '「{{死霊操りしパペットマスター|5482}}」の効果の対象となった悪魔族モンスター2体のうち1体が、チェーンして発動した「{{D.D.クロウ|6980}}」の効果によって、墓地に存在しなくなった場合でも、残り１体のモンスターは墓地から特殊召喚される事になります。\n\nなお、その特殊召喚されたモンスターはこのターンに攻撃する事はできません。', '死霊操リシパペットマスター5482ノ①コノカードガアドバンス召喚ニ成功シタ時2000lpヲ払イ自分ノ墓地ノ悪魔族モンスター2体ヲ対象トシテ発動デキルソノ悪魔族モンスターヲ特殊召喚スルコノ効果デ特殊召喚シタモンスターハコノターン攻撃デキナイ効果ノ発動ニチェーンシテ相手ガd.d.クロウ6980ヲ発動シ対象トナル2体ノ悪魔族モンスターノウチ1体ガ墓地ニ存在シナクナリマシタnnコノ場合効果処理ハドウナリマスカ', '死霊操リシパペットマスター5482ノ効果ノ対象トナッタ悪魔族モンスター2体ノウチ1体ガチェーンシテ発動シタd.d.クロウ6980ノ効果ニヨッテ墓地ニ存在シナクナッタ場合デモ残リ1体ノモンスターハ墓地カラ特殊召喚サレル事ニナリマスnnナオソノ特殊召喚サレタモンスターハコノターンニ攻撃スル事ハデキマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (113, '4041', '自身の『①：１ターンに１度、相手フィールドのモンスター１体を対象として発動できる。その相手モンスターを装備カード扱いとしてこのカードに装備する（１体のみ装備可能）』モンスター効果によって、相手の「{{ブラック・マジシャン|4041}}」を装備カード扱いとして装備している「{{サクリファイス|4737}}」が自分のモンスターゾーンに表側表示で存在しています。\n\nその後、「{{巨大化|4663}}」が発動し、その「{{サクリファイス|4737}}」に装備された場合、攻撃力・守備力の数値はどうなりますか？', '質問の状況の場合、「{{サクリファイス|4737}}」の『②：このカードの攻撃力・守備力は、このカードの効果で装備したモンスターのそれぞれの数値になり、このカードが戦闘で破壊される場合、代わりに装備したそのモンスターを破壊する』モンスター効果が適用されますので、守備力は2100の状態のままとなりますが、攻撃力は「{{巨大化|4663}}」の効果によって、自分と相手のライフポイントの状況によって変化する事になります。\n\n『自分のLPが相手より少ない場合、装備モンスターの攻撃力は元々の攻撃力の倍になる』処理または、『自分のLPが相手より多い場合、装備モンスターの攻撃力は元々の攻撃力の半分になる』処理が適用される間は、「{{サクリファイス|4737}}」の元々の攻撃力となる0の状態になりますが、自分と相手のライフポイントが同じ間は、装備されている「{{ブラック・マジシャン|4041}}」の攻撃力となる2500の状態になります。', '自身ノ①1ターンニ1度相手フィールドノモンスター1体ヲ対象トシテ発動デキルソノ相手モンスターヲ装備カード扱イトシテコノカードニ装備スル1体ノミ装備可能モンスター効果ニヨッテ相手ノブラックマジシャン4041ヲ装備カード扱イトシテ装備シテイルサクリファイス4737ガ自分ノモンスターゾーンニ表側表示デ存在シテイマスnnソノ後巨大化4663ガ発動シソノサクリファイス4737ニ装備サレタ場合攻撃力守備力ノ数値ハドウナリマスカ', '質問ノ状況ノ場合サクリファイス4737ノ②コノカードノ攻撃力守備力ハコノカードノ効果デ装備シタモンスターノソレゾレノ数値ニナリコノカードガ戦闘デ破壊サレル場合代ワリニ装備シタソノモンスターヲ破壊スルモンスター効果ガ適用サレマスノデ守備力ハ2100ノ状態ノママトナリマスガ攻撃力ハ巨大化4663ノ効果ニヨッテ自分ト相手ノライフポイントノ状況ニヨッテ変化スル事ニナリマスnn自分ノlpガ相手ヨリ少ナイ場合装備モンスターノ攻撃力ハ元々ノ攻撃力ノ倍ニナル処理マタハ自分ノlpガ相手ヨリ多イ場合装備モンスターノ攻撃力ハ元々ノ攻撃力ノ半分ニナル処理ガ適用サレル間ハサクリファイス4737ノ元々ノ攻撃力トナル0ノ状態ニナリマスガ自分ト相手ノライフポイントガ同ジ間ハ装備サレテイルブラックマジシャン4041ノ攻撃力トナル2500ノ状態ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (112, '7858', '「{{王宮の鉄壁|7858}}」の適用中に「{{先史遺産技術|10184}}」を発動する事はできますか？\n\nまた、「{{先史遺産技術|10184}}」の発動にチェーンして「{{王宮の鉄壁|7858}}」が発動した場合、効果処理はどうなりますか？', '「{{王宮の鉄壁|7858}}」の適用中に、「{{先史遺産技術|10184}}」を発動する事はできません。\n\nまた、「{{先史遺産技術|10184}}」にチェーンして発動した「{{王宮の鉄壁|7858}}」の効果が適用されている場合、「{{先史遺産技術|10184}}」の対象として選択した自分の墓地の「先史遺産」と名のついたモンスターを除外する事はできません。\nその場合、『その後、自分のデッキの上からカードを２枚確認し、その中から１枚を選んで手札に加え、残りのカードを墓地へ送る』処理を適用する事もできません。\n\nなお、その場合でも、このターンに『自分は「先史遺産」と名のついたモンスター以外のモンスターを特殊召喚できない』事になります。', '王宮ノ鉄壁7858ノ適用中ニ先史遺産技術10184ヲ発動スル事ハデキマスカnnマタ先史遺産技術10184ノ発動ニチェーンシテ王宮ノ鉄壁7858ガ発動シタ場合効果処理ハドウナリマスカ', '王宮ノ鉄壁7858ノ適用中ニ先史遺産技術10184ヲ発動スル事ハデキマセンnnマタ先史遺産技術10184ニチェーンシテ発動シタ王宮ノ鉄壁7858ノ効果ガ適用サレテイル場合先史遺産技術10184ノ対象トシテ選択シタ自分ノ墓地ノ先史遺産ト名ノツイタモンスターヲ除外スル事ハデキマセンnソノ場合ソノ後自分ノデッキノ上カラカードヲ2枚確認シソノ中カラ1枚ヲ選ンデ手札ニ加エ残リノカードヲ墓地ヘ送ル処理ヲ適用スル事モデキマセンnnナオソノ場合デモコノターンニ自分ハ先史遺産ト名ノツイタモンスター以外ノモンスターヲ特殊召喚デキナイ事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (111, '4354', '「{{光の護封剣|4354}}」のカードの発動にチェーンして「{{サイクロン|4909}}」が発動し、その「{{光の護封剣|4354}}」が破壊されました。\n\nその場合、「{{光の護封剣|4354}}」のそれぞれの効果は適用されますか？', '「{{光の護封剣|4354}}」の『①：このカードの発動時の効果処理として、相手フィールドに裏側表示モンスターが存在する場合、そのモンスターを全て表側表示にする』効果は、「{{光の護封剣|4354}}」のカードの発動時の効果処理となりますので、チェーンして発動した「{{サイクロン|4909}}」の効果によって破壊される場合でも、効果処理は通常通り適用されます。\n（裏側表示モンスターは表側表示になります。）\n\nなお、『②：このカードが魔法＆罠ゾーンに存在する限り、相手モンスターは攻撃宣言できない』効果は、「{{光の護封剣|4354}}」が魔法＆罠ゾーンに表側表示で存在する間のみ適用される効果となりますので、「{{光の護封剣|4354}}」が破壊されている場合には適用されません。', '光ノ護封劍4354ノカードノ発動ニチェーンシテサイクロン4909ガ発動シソノ光ノ護封劍4354ガ破壊サレマシタnnソノ場合光ノ護封劍4354ノソレゾレノ効果ハ適用サレマスカ', '光ノ護封劍4354ノ①コノカードノ発動時ノ効果処理トシテ相手フィールドニ裏側表示モンスターガ存在スル場合ソノモンスターヲ全テ表側表示ニスル効果ハ光ノ護封劍4354ノカードノ発動時ノ効果処理トナリマスノデチェーンシテ発動シタサイクロン4909ノ効果ニヨッテ破壊サレル場合デモ効果処理ハ通常通リ適用サレマスn裏側表示モンスターハ表側表示ニナリマスnnナオ②コノカードガ魔法罠ゾーンニ存在スル限リ相手モンスターハ攻撃宣言デキナイ効果ハ光ノ護封劍4354ガ魔法罠ゾーンニ表側表示デ存在スル間ノミ適用サレル効果トナリマスノデ光ノ護封劍4354ガ破壊サレテイル場合ニハ適用サレマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (110, '10015', '「{{白竜の忍者|10015}}」の『このカードがフィールド上に表側表示で存在する限り、自分フィールド上の魔法・罠カードはカードの効果では破壊されない』モンスター効果が適用されている場合、「{{覇王眷竜オッドアイズ|13054}}」の『①：自分フィールドの「覇王眷竜」モンスター１体をリリースして発動できる。このカードを破壊し、デッキから攻撃力１５００以下のPモンスター１体を手札に加える』ペンデュラム効果を発動する事はできますか？', '「{{白竜の忍者|10015}}」のモンスター効果が適用されている場合でも、「{{覇王眷竜オッドアイズ|13054}}」のペンデュラム効果を発動する事はできます。\n\nその場合、「{{覇王眷竜オッドアイズ|13054}}」の効果処理の際に、「{{覇王眷竜オッドアイズ|13054}}」自身は破壊されませんので、『デッキから攻撃力１５００以下のPモンスター１体を手札に加える』処理は適用されません。', '白龍ノ忍者10015ノコノカードガフィールド上ニ表側表示デ存在スル限リ自分フィールド上ノ魔法罠カードハカードノ効果デハ破壊サレナイモンスター効果ガ適用サレテイル場合覇王眷龍オッドアイズ13054ノ①自分フィールドノ覇王眷龍モンスター1体ヲリリースシテ発動デキルコノカードヲ破壊シデッキカラ攻撃力1500以下ノpモンスター1体ヲ手札ニ加エルペンデュラム効果ヲ発動スル事ハデキマスカ', '白龍ノ忍者10015ノモンスター効果ガ適用サレテイル場合デモ覇王眷龍オッドアイズ13054ノペンデュラム効果ヲ発動スル事ハデキマスnnソノ場合覇王眷龍オッドアイズ13054ノ効果処理ノ際ニ覇王眷龍オッドアイズ13054自身ハ破壊サレマセンノデデッキカラ攻撃力1500以下ノpモンスター1体ヲ手札ニ加エル処理ハ適用サレマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (109, '5242', '「{{聖獣セルケト|5242}}」がモンスター トークンや、モンスターカードとして扱われている「{{アポピスの化神|5234}}」を戦闘で破壊した場合、「{{聖獣セルケト|5242}}」の『③：このカードが戦闘でモンスターを破壊した場合に発動する。このカードの攻撃力は５００アップする』効果は発動しますか？', '「{{聖獣セルケト|5242}}」がモンスタートークンや、モンスターカードとして扱われている「{{アポピスの化神|5234}}」を戦闘で破壊した場合でも、「{{聖獣セルケト|5242}}」の効果は発動し、攻撃力が500アップします。', '聖獣セルケト5242ガモンスタートークンヤモンスターカードトシテ扱ワレテイルアポピスノ化神5234ヲ戦闘デ破壊シタ場合聖獣セルケト5242ノ③コノカードガ戦闘デモンスターヲ破壊シタ場合ニ発動スルコノカードノ攻撃力ハ500アップスル効果ハ発動シマスカ', '聖獣セルケト5242ガモンスタートークンヤモンスターカードトシテ扱ワレテイルアポピスノ化神5234ヲ戦闘デ破壊シタ場合デモ聖獣セルケト5242ノ効果ハ発動シ攻撃力ガ500アップシマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (107, '7858', '「{{王宮の鉄壁|7858}}」の『①：このカードが魔法＆罠ゾーンに存在する限り、お互いにカードを除外できない』効果が適用されている場合、「{{水晶機巧－シトリィ|12606}}」の『①：相手のメインフェイズ及びバトルフェイズに、チューナー以外の自分の墓地のモンスター１体を対象として発動できる。そのモンスターを効果を無効にして特殊召喚し、そのモンスターとこのカードのみを素材として機械族Sモンスター１体をS召喚する。その時のS素材モンスターは墓地へは行かず除外される』モンスター効果を発動する事はできますか？', '「{{王宮の鉄壁|7858}}」の効果が適用されている場合でも、「{{水晶機巧－シトリィ|12606}}」のモンスター効果を発動する事はできます。\n\n『そのモンスターを効果を無効にして特殊召喚し、そのモンスターとこのカードのみを素材として機械族Sモンスター１体をS召喚する』効果処理は通常通り行われます。\n\nただし、「{{王宮の鉄壁|7858}}」の効果が適用されていますので、シンクロ素材モンスターは除外されず、墓地へ送られる事になります。', '王宮ノ鉄壁7858ノ①コノカードガ魔法罠ゾーンニ存在スル限リオ互イニカードヲ除外デキナイ効果ガ適用サレテイル場合水晶機巧シトリィ12606ノ①相手ノメインフェイズ及ビバトルフェイズニチューナー以外ノ自分ノ墓地ノモンスター1体ヲ対象トシテ発動デキルソノモンスターヲ効果ヲ無効ニシテ特殊召喚シソノモンスタートコノカードノミヲ素材トシテ機械族sモンスター1体ヲs召喚スルソノ時ノs素材モンスターハ墓地ヘハ行カズ除外サレルモンスター効果ヲ発動スル事ハデキマスカ', '王宮ノ鉄壁7858ノ効果ガ適用サレテイル場合デモ水晶機巧シトリィ12606ノモンスター効果ヲ発動スル事ハデキマスnnソノモンスターヲ効果ヲ無効ニシテ特殊召喚シソノモンスタートコノカードノミヲ素材トシテ機械族sモンスター1体ヲs召喚スル効果処理ハ通常通リ行ワレマスnnタダシ王宮ノ鉄壁7858ノ効果ガ適用サレテイマスノデシンクロ素材モンスターハ除外サレズ墓地ヘ送ラレル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (106, '5197', '自分フィールドに「{{ビッグバンガール|5197}}」が表側表示で存在しています。\n\nその「{{ビッグバンガール|5197}}」を対象として発動した「{{強制脱出装置|5914}}」にチェーンして「{{非常食|5350}}」を発動した場合、「{{ビッグバンガール|5197}}」の効果は適用されますか？', '「{{ビッグバンガール|5197}}」の効果は永続効果となります。\n\n質問の状況の場合、チェーン２にて発動した「{{非常食|5350}}」の効果処理が完了した時点で、「{{ビッグバンガール|5197}}」の効果が適用され、『相手ライフに５００ポイントダメージを与える』処理を行い、次に、チェーン１の「{{強制脱出装置|5914}}」の効果処理が行われる事になります。', '自分フィールドニビッグバンガール5197ガ表側表示デ存在シテイマスnnソノビッグバンガール5197ヲ対象トシテ発動シタ強制脱出装置5914ニチェーンシテ非常食5350ヲ発動シタ場合ビッグバンガール5197ノ効果ハ適用サレマスカ', 'ビッグバンガール5197ノ効果ハ永続効果トナリマスnn質問ノ状況ノ場合チェーン2ニテ発動シタ非常食5350ノ効果処理ガ完了シタ時点デビッグバンガール5197ノ効果ガ適用サレ相手ライフニ500ポイントダメージヲ与エル処理ヲ行イ次ニチェーン1ノ強制脱出装置5914ノ効果処理ガ行ワレル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (105, '7735', '自分の墓地に「{{レッド・デーモンズ・ドラゴン|7735}}」、「{{ブラック・ローズ・ドラゴン|7898}}」、「{{ブラックフェザー・ドラゴン|8815}}」、「{{エンシェント・フェアリー・ドラゴン|8090}}」、「{{ライフ・ストリーム・ドラゴン|9509}}」の5体が存在する状態で、「{{集いし願い|13001}}」の『①：自分の墓地にドラゴン族Sモンスターが５種類以上存在する場合に発動できる。エクストラデッキから「{{スターダスト・ドラゴン|7734}}」１体をS召喚扱いで特殊召喚し、このカードを装備する。この効果で特殊召喚したモンスターはエンドフェイズに除外される』効果を発動しました。\n\nその発動にチェーンして、相手が「{{D.D.クロウ|6980}}」のモンスター効果を発動し、自分の墓地のドラゴン族のシンクロモンスターが4体以下になった場合、「{{集いし願い|13001}}」の処理はどうなりますか？', '「{{集いし願い|13001}}」のカードの発動にチェーンして発動したカードの効果によって、効果処理時に自分の墓地に存在するドラゴン族モンスターが4体以下になっている場合でも、効果処理は通常通り適用されます。\n（エクストラデッキから「{{スターダスト・ドラゴン|7734}}」は特殊召喚され、装備されます。エンドフェイズに除外される処理や、「{{集いし願い|13001}}」が装備されている際に適用される効果も通常通り適用されます。）', '自分ノ墓地ニレッドデーモンズドラゴン7735ブラックローズドラゴン7898ブラックフェザードラゴン8815エンシェントフェアリードラゴン8090ライフストリームドラゴン9509ノ5体ガ存在スル状態デ集イシ願イ13001ノ①自分ノ墓地ニドラゴン族sモンスターガ5種類以上存在スル場合ニ発動デキルエクストラデッキカラスターダストドラゴン77341体ヲs召喚扱イデ特殊召喚シコノカードヲ装備スルコノ効果デ特殊召喚シタモンスターハエンドフェイズニ除外サレル効果ヲ発動シマシタnnソノ発動ニチェーンシテ相手ガd.d.クロウ6980ノモンスター効果ヲ発動シ自分ノ墓地ノドラゴン族ノシンクロモンスターガ4体以下ニナッタ場合集イシ願イ13001ノ処理ハドウナリマスカ', '集イシ願イ13001ノカードノ発動ニチェーンシテ発動シタカードノ効果ニヨッテ効果処理時ニ自分ノ墓地ニ存在スルドラゴン族モンスターガ4体以下ニナッテイル場合デモ効果処理ハ通常通リ適用サレマスnエクストラデッキカラスターダストドラゴン7734ハ特殊召喚サレ装備サレマスエンドフェイズニ除外サレル処理ヤ集イシ願イ13001ガ装備サレテイル際ニ適用サレル効果モ通常通リ適用サレマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (104, '6181', '装備魔法カード扱いとなっている「${{強化支援メカ・ヘビーウェポン|6181}}」が破壊された時、「{{マシン・デベロッパー|8668}}」の『フィールド上の機械族モンスターが戦闘またはカードの効果によって破壊される度に、このカードにジャンクカウンターを２つ置く』効果は適用されますか？', '装備魔法カード扱いとなっている「${{強化支援メカ・ヘビーウェポン|6181}}」は破壊された際に機械族モンスターとしては扱われていませんので、「{{マシン・デベロッパー|8668}}」にジャンクカウンターは置かれません。', '装備魔法カード扱イトナッテイル強化支援メカヘビーウェポン6181ガ破壊サレタ時マシンデベロッパー8668ノフィールド上ノ機械族モンスターガ戦闘マタハカードノ効果ニヨッテ破壊サレル度ニコノカードニジャンクカウンターヲ2ツ置ク効果ハ適用サレマスカ', '装備魔法カード扱イトナッテイル強化支援メカヘビーウェポン6181ハ破壊サレタ際ニ機械族モンスタートシテハ扱ワレテイマセンノデマシンデベロッパー8668ニジャンクカウンターハ置カレマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (103, '6682', '相手の魔法＆罠ゾーンに「{{マクロコスモス|6682}}」が表側表示で存在し、『このカードがフィールド上に存在する限り、墓地へ送られるカードは墓地へは行かずゲームから除外される』効果が適用されています。\n\nこの状況で、自分は「{{NEX|7162}}」の『自分フィールド上に表側表示で存在する「N」と名のついたモンスター１体を墓地へ送り、墓地へ送ったカードと同名カード扱いのレベル４モンスター１体を融合デッキから特殊召喚する』効果を発動する事はできますか？', '「{{マクロコスモス|6682}}」の適用中に「{{NEX|7162}}」を発動する事はできます。\n\nその場合、対象として選択した「N」と名の付いたモンスター1体は、墓地へは送られず、「{{マクロコスモス|6682}}」の効果によって除外されますので、『墓地へ送ったカードと同名カード扱いのレベル４モンスター１体を融合デッキから特殊召喚する』処理は適用されません。', '相手ノ魔法罠ゾーンニマクロコスモス6682ガ表側表示デ存在シコノカードガフィールド上ニ存在スル限リ墓地ヘ送ラレルカードハ墓地ヘハ行カズゲームカラ除外サレル効果ガ適用サレテイマスnnコノ状況デ自分ハnex7162ノ自分フィールド上ニ表側表示デ存在スルnト名ノツイタモンスター1体ヲ墓地ヘ送リ墓地ヘ送ッタカードト同名カード扱イノレベル4モンスター1体ヲ融合デッキカラ特殊召喚スル効果ヲ発動スル事ハデキマスカ', 'マクロコスモス6682ノ適用中ニnex7162ヲ発動スル事ハデキマスnnソノ場合対象トシテ選択シタnト名ノ付イタモンスター1体ハ墓地ヘハ送ラレズマクロコスモス6682ノ効果ニヨッテ除外サレマスノデ墓地ヘ送ッタカードト同名カード扱イノレベル4モンスター1体ヲ融合デッキカラ特殊召喚スル処理ハ適用サレマセン');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (102, '6486', '攻撃表示でモンスターへの攻撃を宣言した「{{E・HERO ランパートガンナー|6486}}」を対象として、相手がバトルステップに「{{エネミーコントローラー|5505}}」を発動しました。\n\nその結果、その「{{E・HERO ランパートガンナー|6486}}」が守備表示になった場合、その攻撃はどうなりますか？', '攻撃表示でモンスターへの攻撃を宣言した「{{E・HERO ランパートガンナー|6486}}」が、そのバトルステップに発動した「{{エネミーコントローラー|5505}}」の効果によって守備表示になった場合、戦闘の巻き戻しが発生します。\n\nその場合、「{{E・HERO ランパートガンナー|6486}}」自身の『このカードが表側守備表示の場合、守備表示の状態で相手プレイヤーを直接攻撃する事ができる。その場合、このカードの攻撃力はダメージ計算時のみ半分になる』効果によって直接攻撃を行うか、攻撃を取りやめるかを選ぶ事になります。', '攻撃表示デモンスターヘノ攻撃ヲ宣言シタeheroランパートガンナー6486ヲ対象トシテ相手ガバトルステップニエネミーコントローラー5505ヲ発動シマシタnnソノ結果ソノeheroランパートガンナー6486ガ守備表示ニナッタ場合ソノ攻撃ハドウナリマスカ', '攻撃表示デモンスターヘノ攻撃ヲ宣言シタeheroランパートガンナー6486ガソノバトルステップニ発動シタエネミーコントローラー5505ノ効果ニヨッテ守備表示ニナッタ場合戦闘ノ巻キ戻シガ発生シマスnnソノ場合eheroランパートガンナー6486自身ノコノカードガ表側守備表示ノ場合守備表示ノ状態デ相手プレイヤーヲ直接攻撃スル事ガデキルソノ場合コノカードノ攻撃力ハダメージ計算時ノミ半分ニナル効果ニヨッテ直接攻撃ヲ行ウカ攻撃ヲ取リヤメルカヲ選ブ事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (101, '11568', '表側守備表示の「{{超重荒神スサノ－O|11568}}」が『①：このカードは表側守備表示のままで攻撃できる。その場合、このカードは守備力を攻撃力として扱いダメージ計算を行う』効果によって攻撃を行った際、そのダメージ計算時に「{{禁じられた聖典|11096}}」が発動し、『ダメージステップ終了時まで、このカード以外のフィールド上のカードの効果は無効化され、その戦闘のダメージ計算は元々の攻撃力・守備力で行う』効果が適用された場合、攻撃はどうなりますか？', '質問の状況の場合、「{{禁じられた聖典|11096}}」の効果で「{{超重荒神スサノ－O|11568}}」の効果が無効になった事によって、「{{超重荒神スサノ－O|11568}}」は表側守備表示の状態で攻撃を行う事ができなくなります。\n\nしたがって、その場合には戦闘ダメージ計算は行われず、ダメージステップが終了する事になります。', '表側守備表示ノ超重荒神スサノo11568ガ①コノカードハ表側守備表示ノママデ攻撃デキルソノ場合コノカードハ守備力ヲ攻撃力トシテ扱イダメージ計算ヲ行ウ効果ニヨッテ攻撃ヲ行ッタ際ソノダメージ計算時ニ禁ジラレタ聖典11096ガ発動シダメージステップ終了時マデコノカード以外ノフィールド上ノカードノ効果ハ無効化サレソノ戦闘ノダメージ計算ハ元々ノ攻撃力守備力デ行ウ効果ガ適用サレタ場合攻撃ハドウナリマスカ', '質問ノ状況ノ場合禁ジラレタ聖典11096ノ効果デ超重荒神スサノo11568ノ効果ガ無効ニナッタ事ニヨッテ超重荒神スサノo11568ハ表側守備表示ノ状態デ攻撃ヲ行ウ事ガデキナクナリマスnnシタガッテソノ場合ニハ戦闘ダメージ計算ハ行ワレズダメージステップガ終了スル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (100, '12818', '「{{灼銀の機竜|12818}}」の『②：S召喚したこのカードが効果で破壊され墓地へ送られた場合、除外されている自分のチューナー１体を対象として発動できる。そのモンスターを手札に加える』モンスター効果を発動する場合、対象として、除外されている「{{テセウスの魔棲物|12871}}」や「{{たつのこ|11660}}」を選択する事はできますか？', '墓地で発動する「{{灼銀の機竜|12818}}」のモンスター効果の対象として、除外されている融合・シンクロモンスターのチューナーを選択する事はできます。\n\nその場合、対象とした融合・シンクロモンスターのチューナーは手札ではなく持ち主のエクストラデッキに加える事になります。', '灼銀ノ機龍12818ノ②s召喚シタコノカードガ効果デ破壊サレ墓地ヘ送ラレタ場合除外サレテイル自分ノチューナー1体ヲ対象トシテ発動デキルソノモンスターヲ手札ニ加エルモンスター効果ヲ発動スル場合対象トシテ除外サレテイルテセウスノ魔棲物12871ヤタツノコ11660ヲ選択スル事ハデキマスカ', '墓地デ発動スル灼銀ノ機龍12818ノモンスター効果ノ対象トシテ除外サレテイル融合シンクロモンスターノチューナーヲ選択スル事ハデキマスnnソノ場合対象トシタ融合シンクロモンスターノチューナーハ手札デハナク持チ主ノエクストラデッキニ加エル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (99, '11094', '墓地にて発動した「{{コアキメイルの金剛核|11094}}」の『自分のメインフェイズ時に墓地のこのカードをゲームから除外して発動できる。このターン、自分フィールド上の「コアキメイル」と名のついたモンスターは破壊されない』効果が適用されているターン、自分フィールドの「{{コアキメイル・オーバードーズ|11553}}」に「{{禁じられた聖槍|9352}}」の効果が適用された場合、その「{{コアキメイル・オーバードーズ|11553}}」は相手フィールドの「{{グングニールの影霊衣|11564}}」の効果によって破壊されますか？', '「{{コアキメイルの金剛核|11094}}」の『このターン、自分フィールド上の「コアキメイル」と名のついたモンスターは破壊されない』効果が適用されているターン、自分フィールドの「コアキメイル」と名のついたモンスターに「{{禁じられた聖槍|9352}}」の効果が適用された場合、魔法・罠カードの効果を受けなくなりますので、「{{コアキメイルの金剛核|11094}}」の効果の適用も受けなくなります。\n\nしたがって、質問の状況の場合、「{{コアキメイル・オーバードーズ|11553}}」は「{{グングニールの影霊衣|11564}}」のモンスター効果によって通常通り破壊される事になります。', '墓地ニテ発動シタコアキメイルノ金剛核11094ノ自分ノメインフェイズ時ニ墓地ノコノカードヲゲームカラ除外シテ発動デキルコノターン自分フィールド上ノコアキメイルト名ノツイタモンスターハ破壊サレナイ効果ガ適用サレテイルターン自分フィールドノコアキメイルオーバードーズ11553ニ禁ジラレタ聖槍9352ノ効果ガ適用サレタ場合ソノコアキメイルオーバードーズ11553ハ相手フィールドノグングニールノ影霊衣11564ノ効果ニヨッテ破壊サレマスカ', 'コアキメイルノ金剛核11094ノコノターン自分フィールド上ノコアキメイルト名ノツイタモンスターハ破壊サレナイ効果ガ適用サレテイルターン自分フィールドノコアキメイルト名ノツイタモンスターニ禁ジラレタ聖槍9352ノ効果ガ適用サレタ場合魔法罠カードノ効果ヲ受ケナクナリマスノデコアキメイルノ金剛核11094ノ効果ノ適用モ受ケナクナリマスnnシタガッテ質問ノ状況ノ場合コアキメイルオーバードーズ11553ハグングニールノ影霊衣11564ノモンスター効果ニヨッテ通常通リ破壊サレル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (98, '6682', '相手の魔法＆罠ゾーンに「{{マクロコスモス|6682}}」が表側表示で存在し、『②：このカードが魔法＆罠ゾーンに存在する限り、墓地へ送られるカードは墓地へは行かず除外される』効果が適用されています。\n\nこの状況で、自分は「{{竜の渓谷|9049}}」の『①：１ターンに１度、手札を１枚捨て、以下の効果から１つを選択して発動できる』効果を発動する事はできますか？', '質問の状況の場合でも、「{{竜の渓谷|9049}}」の効果を発動する事はできます。\n効果を発動する際に、コストとして捨てる手札は「{{マクロコスモス|6682}}」の効果によって、墓地へは送られず、除外される事になりますが、効果処理は通常通り適用されます。\n\nなお、『●デッキからドラゴン族モンスター１体を墓地へ送る』効果を選択して発動している場合には、その処理によってデッキから選んだドラゴン族モンスターも「{{マクロコスモス|6682}}」の効果によって、墓地へは送られず、除外される事になります。', '相手ノ魔法罠ゾーンニマクロコスモス6682ガ表側表示デ存在シ②コノカードガ魔法罠ゾーンニ存在スル限リ墓地ヘ送ラレルカードハ墓地ヘハ行カズ除外サレル効果ガ適用サレテイマスnnコノ状況デ自分ハ龍ノ渓谷9049ノ①1ターンニ1度手札ヲ1枚捨テ以下ノ効果カラ1ツヲ選択シテ発動デキル効果ヲ発動スル事ハデキマスカ', '質問ノ状況ノ場合デモ龍ノ渓谷9049ノ効果ヲ発動スル事ハデキマスn効果ヲ発動スル際ニコストトシテ捨テル手札ハマクロコスモス6682ノ効果ニヨッテ墓地ヘハ送ラレズ除外サレル事ニナリマスガ効果処理ハ通常通リ適用サレマスnnナオ●デッキカラドラゴン族モンスター1体ヲ墓地ヘ送ル効果ヲ選択シテ発動シテイル場合ニハソノ処理ニヨッテデッキカラ選ンダドラゴン族モンスターモマクロコスモス6682ノ効果ニヨッテ墓地ヘハ送ラレズ除外サレル事ニナリマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (97, '11166', '「{{ドゥーブルパッセ|11166}}」の効果によって、相手モンスターの攻撃がプレイヤーへの直接攻撃へと変更されました。\nその直接攻撃による戦闘ダメージ計算が行われる前のバトルステップにて、「{{超電磁タートル|11120}}」の効果が発動し、バトルフェイズが終了した場合、自分のモンスターは次の自分のターンに直接攻撃を行う事ができますか？', '「{{ドゥーブルパッセ|11166}}」の効果によって、相手モンスターの攻撃は自分への直接攻撃となりますが、「{{ドゥーブルパッセ|11166}}」の効果処理によってそのまま戦闘ダメージ計算までが行われるわけではありません。\n（相手モンスターの攻撃が自分への直接攻撃となった後に、他のカードの効果を発動する事はできます。）\n\nしたがって、そのバトルステップにて「{{超電磁タートル|11120}}｣の効果が発動し、バトルフェイズが終了したのであれば、相手モンスターの直接攻撃は行われず、バトルフェイズが終了します。\nその場合でも、『その自分のモンスターは、次の自分ターンに直接攻撃できる』は適用されます。', 'ドゥーブルパッセ11166ノ効果ニヨッテ相手モンスターノ攻撃ガプレイヤーヘノ直接攻撃ヘト変更サレマシタnソノ直接攻撃ニヨル戦闘ダメージ計算ガ行ワレル前ノバトルステップニテ超電磁タートル11120ノ効果ガ発動シバトルフェイズガ終了シタ場合自分ノモンスターハ次ノ自分ノターンニ直接攻撃ヲ行ウ事ガデキマスカ', 'ドゥーブルパッセ11166ノ効果ニヨッテ相手モンスターノ攻撃ハ自分ヘノ直接攻撃トナリマスガドゥーブルパッセ11166ノ効果処理ニヨッテソノママ戦闘ダメージ計算マデガ行ワレルワケデハアリマセンn相手モンスターノ攻撃ガ自分ヘノ直接攻撃トナッタ後ニ他ノカードノ効果ヲ発動スル事ハデキマスnnシタガッテソノバトルステップニテ超電磁タートル11120｣ノ効果ガ発動シバトルフェイズガ終了シタノデアレバ相手モンスターノ直接攻撃ハ行ワレズバトルフェイズガ終了シマスnソノ場合デモソノ自分ノモンスターハ次ノ自分ターンニ直接攻撃デキルハ適用サレマス');
INSERT OR IGNORE INTO faqs (faq_id, card_id, question, answer, normalized_question, normalized_answer) VALUES (96, '12337', '「{{儀式の下準備|12337}}」の『①：デッキから儀式魔法カード１枚を選び、さらにその儀式魔法カードにカード名が記された儀式モンスター１体を自分のデッキ・墓地から選ぶ。そのカード２枚を手札に加える』効果で、「{{ネフティスの輪廻|14017}}」を手札に加える事はできますか？', '「{{儀式の下準備|12337}}」の効果によって、「{{ネフティスの輪廻|14017}}」を手札に加える事はできます。\n\nなお、『さらにその儀式魔法カードにカード名が記された儀式モンスター１体を自分のデッキ・墓地から選ぶ』処理によって選ぶ儀式モンスターは、「{{ネフティスの祀り手|14013}}」か「{{ネフティスの蒼凰神|14014}}」のいずれか1体となります。\n（自分のデッキに「{{ネフティスの輪廻|14017}}」が存在し、自分のデッキまたは自分の墓地に「{{ネフティスの祀り手|14013}}」か「{{ネフティスの蒼凰神|14014}}」のいずれか1体が存在していれば、「{{儀式の下準備|12337}}」を発動する事ができます。）', '儀式ノ下準備12337ノ①デッキカラ儀式魔法カード1枚ヲ選ビサラニソノ儀式魔法カードニカード名ガ記サレタ儀式モンスター1体ヲ自分ノデッキ墓地カラ選ブソノカード2枚ヲ手札ニ加エル効果デネフティスノ輪廻14017ヲ手札ニ加エル事ハデキマスカ', '儀式ノ下準備12337ノ効果ニヨッテネフティスノ輪廻14017ヲ手札ニ加エル事ハデキマスnnナオサラニソノ儀式魔法カードニカード名ガ記サレタ儀式モンスター1体ヲ自分ノデッキ墓地カラ選ブ処理ニヨッテ選ブ儀式モンスターハネフティスノ祀リ手14013カネフティスノ蒼凰神14014ノイズレカ1体トナリマスn自分ノデッキニネフティスノ輪廻14017ガ存在シ自分ノデッキマタハ自分ノ墓地ニネフティスノ祀リ手14013カネフティスノ蒼凰神14014ノイズレカ1体ガ存在シテイレバ儀式ノ下準備12337ヲ発動スル事ガデキマス');
